NAME = 'ACV: A Conservative Version'
BOOK = 'II Samuel'

CHAPTERS = {
    1: {
        1: 'Zgodi se pa po smrti Savlovi, ko se je bil David vrnil od poboja Amalekovcev in je bival dva dni v Ziklagu,',
        2: 'glej, tretjega dne pride mož iz tabora Savlove vojske z raztrganimi oblačili in s prstjo na glavi. In ko dospe k Davidu, pade na tla in se pokloni.',
        3: 'In David mu reče: Odkod prihajaš? On mu reče: Iz tabora Izraelovega sem ubežal.',
        4: 'David ga vpraša: Kako se je godilo? Povej mi, prosim. On odgovori: Ljudstvo je bežalo iz boja in je tudi dosti ljudstva padlo in poginilo, tudi Savel in njegov sin Jonatan sta mrtva.',
        5: 'In David reče mladeniču, ki mu je to pravil: Kako veš, da sta mrtva Savel in njegov sin Jonatan?',
        6: 'Mladenič, ki mu je to pravil, reče: Po naključbi sem prišel na goro Gilboo, in glej, Savel se je bil naslonil na sulico svojo, in glej, vozovi in jezdeci so hiteli za njim.',
        7: 'In ko se ozre, me ugleda in me pokliče. In jaz odvrnem: Tu sem!',
        8: 'On pa mi reče: Kdo si ti? Rečem mu: Amalekovec sem.',
        9: 'Nato mi veli: Stopi k meni in me usmrti, kajti groza se me je lotila, ker še je duša docela v meni!',
        10: 'In stopil sem k njemu in ga usmrtil, ker sem vedel, da ne more živeti po svojem padcu. In vzel sem venec, ki ga je imel na glavi, in zapestnico z roke njegove, in sem ju zdaj prinesel tebi, gospodu svojemu!',
        11: 'Tedaj prime David za oblačila svoja in jih raztrga, enako tudi vsi možje, ki so bili pri njem;',
        12: 'in so žalovali in jokali in se postili do večera po Savlu in po Jonatanu, sinu njegovem, in zavoljo ljudstva Gospodovega in hiše Izraelove, ker so bili padli po meču.',
        13: 'In David reče mladeniču, ki mu je to naznanil: Odkod si? Odgovori: Sin sem tujca, Amalekovca.',
        14: 'In David mu reče: Kako, da se nisi bal položiti roke svoje na maziljenca Gospodovega, da ga pogubiš?',
        15: 'In pokliče David enega mladeničev svojih in veli: Stopi sem in ga umori! In ga je udaril, da je umrl.',
        16: 'In David mu reče: Kri tvoja bodi na glavi tvoji! Zakaj tvoja usta so zoper tebe pričala, rekoč: Jaz sem usmrtil maziljenca Gospodovega.',
        17: 'In David je pel to žalostinko nad Savlom in Jonatanom, sinom njegovim,',
        18: 'in je velel, da se nauče sinovi Judovi pesem „o loku“; glej, zapisana je v knjigi Jašarjevi:',
        19: 'Slava tvoja, o Izrael, je bila ubita na višinah tvojih! Kako so padli junaki!',
        20: 'Ne pravite tega v Gatu, ne oznanjujte po ulicah v Askelonu, da se ne vesele hčere Filistejcev, da ne vriskajo radostno neobrezancev hčere!',
        21: 'O gore Gilboe, da ne bi bilo rose ali dežja na vas, ne njiv, s katerih bi se prinašale daritve! Ker ondi je bil junakom ščit s sramoto odvržen, ščit Savlov, kakor bi ne bil z oljem maziljen.',
        22: 'Brez krvi pobitih, brez tolstine junakov se ni vračal lok Jonatanov, in meč Savlov ni prišel nikoli prazen nazaj.',
        23: 'Savel in Jonatan, ljubezniva in draga sta bila v življenju, tudi v smrti nista ločena; bila sta hitrejša nego orli, močnejša nego levi.',
        24: 'Hčere Izraelove, plakajte po Savlu, ki vas je mično oblačil v škrlat in je deval dragotine zlate na obleke vaše!',
        25: 'Kako so padli junaki sredi boja! Jonatan je bil ubit na višinah tvojih.',
        26: 'Žal mi je tebe, brat moj Jonatan; drag si mi bil jako! Divna mi je bila ljubezen tvoja, bolj nego žená ljubezen.',
        27: 'Kako so padli junaki in je poginilo vojno orožje!',
    },
    2: {
        1: 'In zgodi se potem, da je David vprašal Gospoda, rekoč: Naj li grem gori v katero mest Judovih? In Gospod mu reče: Pojdi! In David vpraša: Kam naj grem? Veli: V Hebron!',
        2: 'David torej gre gori in tudi dve ženi njegovi, Ahinoama Jezreelska in Abigaila, bivša žena Nabala Karmelskega.',
        3: 'Tudi može, ki so bili pri njem, je pripeljal David gori, vsakega z družino njegovo, in prebivali so v hebronskih mestih.',
        4: 'In prišli so možje Judovi in so ondi pomazilili Davida za kralja hiši Judovi. In ko so povedali Davidu, da so možje iz Jabesa v Gileadu pokopali Savla,',
        5: 'pošlje sle k možem v Gileadski Jabes in jim sporoči: Blagoslovljeni bodite od Gospoda, da ste izkazali to milost gospodu svojemu, Savlu, in ste ga pokopali!',
        6: 'Sedaj pa izkaži Gospod milost in zvestobo vam, pa tudi jaz povrnem to dobro delo vam, ki ste ga storili.',
        7: 'Sedaj torej naj bodo močne roke vaše in hrabri bodite! Kajti Savel, gospod vaš, je mrtev, in mene je pomazilila hiša Judova sebi za kralja.',
        8: 'Abner pa, sin Nerov, poveljnik Savlove vojske, je vzel Isboseta, Savlovega sina, ter ga je prepeljal v Mahanaim',
        9: 'in postavil za kralja nad Gileadom in nad Asurskimi in nad Jezreelom in Efraimom in Benjaminom in nad vsem Izraelom.',
        10: 'Isboset, sin Savlov, je bil štirideset let star, ko je zakraljeval Izraelu, in vladal je dve leti. Samo hiša Judova je šla za Davidom.',
        11: 'Časa pa, ki je v njem kraljeval David v Hebronu hiši Judovi, je bilo sedem let in šest mesecev.',
        12: 'In Abner, sin Nerov, je odrinil s hlapci Isboseta, Savlovega sina, iz Mahanaima v Gibeon.',
        13: 'Tudi Joab, sin Zervijin, in hlapci Davidovi so odrinili, in so se srečali pri ribniku v Gibeonu; in sedejo eni na oni strani ribnika, drugi pa na tej strani ribnika.',
        14: 'Abner pa reče Joabu: Vstanejo naj mladeniči in igrajo boj pred nami. In Joab reče: Naj vstanejo!',
        15: 'Tedaj vstanejo in nastopijo po številu: dvanajst za Benjamina in za Isboseta, sina Savlovega, in dvanajst iz hlapcev Davidovih.',
        16: 'In zgrabi vsakteri svojega nasprotnika za glavo in mu zasadi meč v stran, in popadajo skupaj. Zato se tisto mesto imenuje Helkat-hazurim, ki je v Gibeonu.',
        17: 'In vnel se je zelo trd boj tisti dan, in hlapci Davidovi porazijo Abnerja in može Izraelove.',
        18: 'Bili so pa ondi trije sinovi Zervije: Joab in Abisaj in Asahel. In Asahel je bil lahkih nog kakor katera izmed srn, ki živé na polju.',
        19: 'In Asahel je podil Abnerja in se ni obrnil ne na desno, ne na levo, tekoč za Abnerjem.',
        20: 'Tedaj se ozre Abner in reče: Si li ti Asahel? Odgovori: Sem.',
        21: 'In Abner mu veli: Obrni se ali na desno ali na levo in primi teh mladeničev enega in si vzemi njegovo orožje! Ali Asahel se ni hotel odvrniti od njega.',
        22: 'In Abner zopet veli Asahelu: V stran kreni, ne hodi za menoj! Zakaj hočeš, da te pobijem na tla? Kako bi smel potem stopiti bratu tvojemu Joabu pred oči?',
        23: 'Vendar pa ni hotel kreniti od njega; zato ga Abner udari z zadnjim koncem sulice v trebuh, da mu je pogledala sulica odzadaj, in pade ondi in umrje na tistem mestu. In kdorkoli je prišel na mesto, kjer je Asahel padel in umrl, se je ustavil.',
        24: 'Joab in Abisaj pa sta podila Abnerja, in solnce je bilo zašlo, ko sta dospela do griča Ame, ki je pred Giahom, ob poti v Gibeonsko puščavo.',
        25: 'In sinovi Benjaminovi se zbero pri Abnerju ter se skupijo v krdelo, in stopijo na vrh griča.',
        26: 'Tedaj kliče Abner proti Joabu in reče: Bode li meč žrl brez konca? Ne veš li, da nazadnje pride bridkost? Kako dolgo nočeš reči ljudstvu, da naj neha preganjati svoje brate?',
        27: 'In Joab reče: Kakor res Bog živi, ako bi ne bil ti govoril, bi se bilo ljudstvo že davi vrnilo, ne eden ne bi bil tiral brata svojega!',
        28: 'Tedaj zatrobenta Joab, in vse ljudstvo se ustavi, in niso več podili Izraela, niti se več bojevali.',
        29: 'Abner in možje njegovi pa so šli vso noč po nižini in so prešli Jordan ter prehodili ves Bitron in prišli v Mahanaim.',
        30: 'In Joab se vrne od Abnerja, in ko je zbral vse ljudstvo, je manjkalo izmed hlapcev Davidovih devetnajst mož in Asahela.',
        31: 'A hlapci Davidovi so pobili iz Benjamincev in iz Abnerjevega moštva tristo in šestdeset mož, ki so umrli.',
        32: 'In so vzdignili Asahela in ga pokopali v grobu očeta njegovega v Betlehemu. Joab in možje njegovi pa so hodili vso noč, in dan jim je zasvital, ko so dospeli v Hebron.',
    },
    3: {
        1: 'In bil je dolgo boj med hišo Savlovo in hišo Davidovo. In David je čimdalje bolj napredoval, Savlova hiša pa je bolj in bolj pešala.',
        2: 'In Davidu so se rodili sinovi v Hebronu: prvenec je bil Amnon, iz Ahinoame Jezreelske;',
        3: 'drugi pa Kileab, iz Abigaile, bivše žene Nabala Karmelskega; in tretji Absalom, sin Maake, hčere Talmaja, kralja v Gesurju;',
        4: 'četrti Adonija, sin Hagite, in peti Sefatija, sin Abitale;',
        5: 'in šesti Itream iz Egle, žene Davidove. Ti so se rodili Davidu v Hebronu.',
        6: 'In bilo je, dokler sta se bojevali hiša Savlova in hiša Davidova, da se je Abner kazal močnega za hišo Savlovo.',
        7: 'Savel pa je bil imel priležnico, po imenu Ricpo, hčer Ajevo. In Isboset reče Abnerju: Zakaj se družiš z očeta mojega priležnico?',
        8: 'In razjezi se Abner hudo zaradi teh besed Isbosetovih in reče: Sem li jaz pasja glava, ki se oklepa Jude? Danes izkazujem milost hiši očeta tvojega Savla, bratom in prijateljem njegovim, in tebe nisem izdal Davidu v roke, pa ti mi danes očitaš pregrešek s tisto žensko?',
        9: 'Bog naj stori Abnerju to in ono naj pridene, ako ne izvršim, kakor je Gospod prisegel Davidu,',
        10: 'da se vzame kraljestvo od hiše Savlove in se postavi Davidov prestol nad Izraelom in nad Judo, od Dana do Bersebe!',
        11: 'In ni mogel Abnerju odgovoriti besede, ker se ga je bal.',
        12: 'In pošlje Abner poročnike pri tej priči k Davidu in reče: Čigava je dežela? in sporoči: Skleni zavezo z menoj, in glej, roka moja bode s teboj, da potegnem vsega Izraela za teboj!',
        13: 'David reče: Dobro, hočem storiti zavezo s teboj; le eno reč zahtevam od tebe, namreč: ne boš videl obličja mojega, razen da mi prej pripelješ Mihalo, hčer Savlovo, ko prideš, da vidiš obličje moje.',
        14: 'Pošlje tudi David poročnike k Isbosetu, Savlovemu sinu, in sporoči: Daj mi ženo mojo Mihalo, ki sem si jo zaročil s sto sprednjimi kožicami Filistejcev.',
        15: 'In Isboset pošlje in jo vzame od moža njenega, od Faltiela, sina Laisovega.',
        16: 'In njen mož je šel ž njo in spotoma jokal, idoč za njo do Bahurima. Tedaj mu reče Abner: Pojdi, vrni se! In se je vrnil.',
        17: 'In Abner se je zmenil s starejšinami Izraelovimi in dejal: Nekdaj ste želeli, da vam bodi David kralj.',
        18: 'Sedaj pa izvršite to! Zakaj Gospod je govoril o Davidu: Po roki služabnika mojega Davida hočem rešiti ljudstvo svoje Izraela iz roke Filistejcev in iz vseh njih sovražnikov pesti.',
        19: 'Enako je govoril Abner na ušesa Benjamincem. Potem je šel Abner govorit tudi na ušesa Davidu v Hebronu vse, kar se je dobro videlo Izraelu in vsej Benjaminovi hiši.',
        20: 'Pride tedaj Abner k Davidu v Hebron in dvajset mož ž njim. In David napravi gostijo Abnerju in možem, ki so bili pri njem.',
        21: 'In Abner reče Davidu: Vstanem in pojdem in zberem vsega Izraela h gospodu svojemu, kralju, da bi sklenili zavezo s teboj in da boš vsem kraljeval, kakor želi duša tvoja. Nato odpošlje David Abnerja, in ta odide v miru.',
        22: 'In glej, hlapci Davidovi in Joab se vrnejo z bojnega obhoda in prineso veliko plena s seboj. Abner pa ni bil več pri Davidu v Hebronu, zakaj ta ga je bil odposlal, in on je šel v miru.',
        23: 'Ko torej pride Joab z vsem bojnim moštvom, povedo Joabu, rekoč: Abner, sin Nerov, je prišel h kralju, in on ga je pustil, da je šel v miru.',
        24: 'Tedaj gre Joab noter h kralju in reče: Kaj si storil? Glej, Abner je prišel k tebi: zakaj si ga odpustil, da je šel, kamor mu drago?',
        25: 'Poznaš vendar Abnerja, Nerovega sina, da te je prišel varat in pozvedovat, kako hodiš ven in noter, da bi vedel vse, kar delaš.',
        26: 'In ko pride Joab od Davida, pošlje sle za Abnerjem, in privedejo ga od vodnjaka Sire. A David ni vedel za to.',
        27: 'Ko pa se vrne Abner v Hebron, ga potegne Joab na stran pod vrata, da bi na tihem ž njim govoril, in tam ga zabode v trebuh, da je umrl, zaradi krvi Asahela, brata njegovega.',
        28: 'Ko David poslej to zasliši, reče: Nedolžen sem in kraljestvo moje pred Gospodom vekomaj pri krvi Abnerja, sina Nerovega.',
        29: 'Naj pride ta kri na glavo Joabu in na njegovega očeta vso hišo, in hiša Joabova ne bodi nikdar brez človeka, ki ima sluzotok ali gobe, ali ki hodi ob palici, ali ki pade pod mečem, ali ki mu primanjkuje kruha.',
        30: 'Tako sta Joab in Abisaj, brat njegov, umorila Abnerja, zato ker je usmrtil njiju brata Asahela v boju pri Gibeonu.',
        31: 'David pa veli Joabu in vsemu ljudstvu, ki je bilo pri njem: Raztrgajte oblačila svoja in prepašite se z raševnikom in žalujte pred Abnerjem! In David kralj je šel za mrtvaškim odrom.',
        32: 'In pokopali so Abnerja v Hebronu, in kralj je povzdignil glas svoj in jokal pri grobu Abnerjevem, in vse ljudstvo je plakalo.',
        33: 'In kralj je pel žalostinko nad Abnerjem, govoreč: Je li moral umreti Abner, kakor umre nespametnik?',
        34: 'Roke tvoje niso bile zvezane, ne noge tvoje vklenjene v spone; padel si, kakor pade človek pred malopridneži! In vse ljudstvo je plakalo za njim tem bolj.',
        35: 'In vse ljudstvo pride, da nagne Davida, da bi jedel kruh, dokler je še dan; a David priseže, rekoč: Bog mi stóri to in prideni še to, ako okusim kruh ali kaj drugega, dokler ne zajde solnce!',
        36: 'In vse ljudstvo je to priznalo in mu je ugajalo, kakor je bilo sploh, karkoli je storil kralj, dobro v očeh ljudstva.',
        37: 'In spoznalo je vse ljudstvo in ves Izrael tisti dan, da ni prišlo od kralja, da je bil ubit Abner, sin Nerov.',
        38: 'In kralj reče hlapcem svojim: Ne veste li, da je danes padel knez in velikan v Izraelu?',
        39: 'Jaz pa sem še slaboten, čeprav maziljeni kralj. In ta dva moža, sinova Zervijina, sta mi pretrda. Gospod poplačaj tistemu, ki ravna krivično, po krivičnosti njegovi!',
    },
    4: {
        1: 'In ko je slišal Isboset, Savlov sin, da je Abner mrtev v Hebronu, mu omahnejo roke, in ves Izrael se ustraši.',
        2: 'Imel pa je Savlov sin dva moža, poveljnika trum: enemu je bilo ime Baana, drugemu pa Rekab, sinova Rimona Berotčana, izmed sinov Benjaminovih (kajti Berot se tudi šteje k Benjaminu;',
        3: 'bili so pa Berotčani bežali v Gitaim in so ondi prebivali do današnjega dne).',
        4: 'Jonatan pa, Savlov sin, je imel sina, hromega na nogah. Pet let je bil star, ko je prišla vest o Savlu in Jonatanu iz Jezreela; in njegova dojka ga je vzela in bežala, in ko je hitela, da ubeži, je padel in ohromel. In ime mu je bilo Mefiboset.',
        5: 'In sinova Rimona Berotčana, Rekab in Baana, sta šla in dospela, ko je bil dan najbolj vroč, v hišo Isbosetovo, ko je počival na postelji opoldne.',
        6: 'In stopita sredi hiše, kakor da bi hotela vzeti pšenice, in ga zabodeta pod rebra, in Rekab in Baana, brat njegov, zbežita.',
        7: 'Ko sta namreč prišla v hišo in je on ležal v spalnici svoji na postelji, ga udarita in umorita ter mu odsekata glavo, in vzameta glavo njegovo in bežita po poti nižine Arabe vso noč.',
        8: 'In prineseta glavo Isbosetovo Davidu v Hebron in rečeta kralju: Glej, glava Isboseta, sina Savlovega, tvojega sovražnika, ki ti je stregel po življenju! Gospod je danes maščeval gospoda mojega, kralja, nad Savlom in nad semenom njegovim.',
        9: 'David pa odgovori Rekabu in Baanu, bratu njegovemu, sinoma Rimona Berotčana, in jima reče: Kakor res živi Gospod, ki je odrešil dušo mojo vseh bridkosti:',
        10: 'ko mi je tisti oznanil, rekoč: Glej, Savel je mrtev! in je menil, da je vesela vest zame, pa sem ga prijel in umoril v Ziklagu ter mu dal s tem plačilo za vest njegovo:',
        11: 'koliko bolj, ko sta dva brezbožneža umorila pravičnega moža v njegovi hiši na postelji njegovi! nimam li zdaj zahtevati krvi njegove iz vajinih rok in vaju potrebiti z zemlje?',
        12: 'In David zapove mladeničem svojim, in ti so ju umorili in jima odsekali roke in noge in so ju obesili pri ribniku v Hebronu. Glavo Isbosetovo pa so vzeli in jo pokopali v Abnerjevem grobu v Hebronu.',
    },
    5: {
        1: 'Tedaj pridejo vsi rodovi Izraelovi k Davidu v Hebron in ga ogovore, rekoč: Glej, kost smo tvoja in meso tvoje.',
        2: 'In že v prejšnjih časih, ko nam je kraljeval Savel, ti si vodil ven in noter Izraela; in tebi je rekel Gospod: Ti boš pasel ljudstvo moje Izraela in ti bodeš vojvoda Izraelu.',
        3: 'Tako so prišli vsi starejšine Izraelovi h kralju v Hebron; in kralj David je sklenil ž njimi zavezo v Hebronu pred Gospodom. In pomazilili so Davida za kralja Izraelu.',
        4: 'David je bil trideset let star, ko je zakraljeval, in vladal je štirideset let.',
        5: 'V Hebronu je kraljeval Judi sedem let in šest mesecev, v Jeruzalemu pa je kraljeval triintrideset let vsemu Izraelu in Judi.',
        6: 'In kralj in možje njegovi so šli v Jeruzalem zoper Jebusejce, prebivalce v deželi. Ti so govorili Davidu: Ne prideš sem noter, temuč slepci in hromci te odženejo – meneč, David ne more priti tja.',
        7: 'Vendar pa je David dobil grad Sion, to je mesto Davidovo.',
        8: 'Kajti David je dejal tisti dan: Kdor premaga Jebusejce in pride do žlebov in porazi tiste hromce in slepce, ki jih sovraži duša Davidova, bodi poglavar! Odtod pravijo: Slepci in hromci ne pridejo v hišo!',
        9: 'In David se je nastanil v tem gradu in ga je imenoval mesto Davidovo. In David je zidal okoli ob Milu in znotraj.',
        10: 'In David je bolj in bolj napredoval, zakaj Gospod, Bog nad vojskami, je bil ž njim.',
        11: 'In Hiram, kralj v Tiru, je poslal poslance k Davidu in cedrovega lesa in tesarje in zidarje, in zgradili so Davidu hišo.',
        12: 'In David je spoznal, da ga je Gospod potrdil za kralja v Izraelu ter da je povišal kraljestvo njegovo zaradi ljudstva svojega Izraela.',
        13: 'In David si je vzel še več priležnic in žen v Jeruzalemu, potem ko je prišel iz Hebrona; in rodilo se je Davidu še več sinov in hčerá.',
        14: 'Ta pa so imena tistih, ki so se mu rodili v Jeruzalemu: Samua, Sobab, Natan in Salomon,',
        15: 'Ibhar, Elisua, Nefeg in Jafija,',
        16: 'in Elisama, Eliada in Elifelet.',
        17: 'Ko pa Filistejci začujejo, da so pomazilili Davida za kralja nad Izraelom, krenejo vsi gori iskat Davida; David pa, ko je zvedel, odide doli v grad.',
        18: 'Filistejci pa pridejo in se razpostavijo v dolini Refaimov.',
        19: 'In David je vprašal Gospoda, rekoč: Ali naj grem gori zoper Filistejce? In jih li hočeš dati v roko mojo? Gospod pa veli Davidu: Pojdi gori, kajti gotovo ti dam Filistejce v roko!',
        20: 'In David pride v Baalperazim [T. j. mesto pretrga.] in jih porazi ondi ter reče: Gospod je raztrgal sovražnike moje pred menoj, kakor ko vode pretrgajo jez. Zato je imenoval ime tistega kraja Baalperazim.',
        21: 'In pustili so svoje malike ondi, David pa in možje njegovi so jih odnesli.',
        22: 'In Filistejci pridejo zopet gori ter se razpostavijo v dolini Refaimov.',
        23: 'In ko David vpraša Gospoda, mu veli: Ne hodi gori, temuč obidi jih zadaj za njimi, da prideš nadnje od strani murvovih dreves.',
        24: 'In ko začuješ šumenje iz vrhov dreves, kakor da prihaja vojska, tedaj se podvizaj: zakaj tedaj gre Gospod pred teboj, da premaga vojsko Filistejcev.',
        25: 'In David je storil, kakor mu je bil zapovedal Gospod, in pobijal je Filistejce od Gebe do tja, koder se hodi v Gezer.',
    },
    6: {
        1: 'In David je zopet zbral vse izbrano moštvo v Izraelu, trideset tisoč.',
        2: 'In vstane David ter gre z vsem ljudstvom, kar ga je bilo pri njem, iz Baale Judove, da prinese odondod skrinjo Božjo, ob kateri se kliče Ime, ime Gospoda nad vojskami, ki stoluje nad kerubi.',
        3: 'In postavili so skrinjo Božjo na nov voz in jo odnesli iz Abinadabove hiše, ki je bila na griču. Uza in Ahio, sinova Abinadabova, sta vodila novi voz.',
        4: 'In ko so ga peljali s skrinjo Božjo iz hiše Abinadabove na griču, je šel Ahio pred skrinjo;',
        5: 'a David in ves rod Izraelov je igral pred Gospodom na vsakovrstna godala iz cipresovine in na harfe in na strune s petjem in na bobne in zvončke in cimbale.',
        6: 'In ko so prišli h gumnu Nakonovemu, je Uza iztegnil roko po skrinji Božji in jo pridržal, zakaj volom se je izpoddrsnilo.',
        7: 'In vname se jeza Gospodova zoper Uza, in Bog ga udari ondi za njegov pregrešek; in je umrl tam pri skrinji Božji.',
        8: 'In David je bil žalosten, ker je bil Gospod naredil pretrg z Uzom, in imenoval je ta kraj Perez Uza, do današnjega dne.',
        9: 'In David se zboji Gospoda tisti dan, in reče: Kako naj pride skrinja Gospodova k meni?',
        10: 'In David ni hotel nesti skrinje Gospodove k sebi, v mesto Davidovo, temuč jo je dal odnesti v hišo Obededoma Gatovca.',
        11: 'In ostala je skrinja Gospodova v hiši Obededoma Gatovca tri mesece; in Gospod je blagoslovil Obededoma in vso hišo njegovo.',
        12: 'In povedali so kralju Davidu, rekoč: Gospod je blagoslovil hišo Obededomovo in vse, kar je njegovo, zaradi skrinje Božje. David pa gre in z veseljem prenese skrinjo Božjo iz hiše Obededomove gori v mesto Davidovo.',
        13: 'In kolikorkrat so prestopili nosilci skrinje Gospodove šest korakov, je daroval vola in pitanca.',
        14: 'In David je plesal z vso močjo pred Gospodom in bil je opasan s platnenim naramnikom.',
        15: 'Tako je prenesel David in vsa hiša Izraelova skrinjo Gospodovo gori z radostnim petjem in glasom trombe.',
        16: 'In ko je prišla skrinja Gospodova v mesto Davidovo, je gledala Mihala, hči Savlova, skozi okno in je videla kralja Davida, da poskakuje in pleše pred Gospodom, in ga je zaničevala v srcu svojem.',
        17: 'Ko so pa prinesli skrinjo Gospodovo noter, jo postavijo na nje mesto sredi šatora, ki ga je bil David razpel zanjo. In David je daroval žgalne in mirovne daritve pred Gospodom.',
        18: 'In ko je David končal darovanje žgalščin in mirovnih žrtev, je blagoslovil ljudstvo v imenu Gospoda nad vojskami',
        19: 'in je podelil vsemu ljudstvu, vsej množici Izraelovi, možem in ženam, vsakemu hlebček kruha in kos mesa in kepo suhega grozdja. In ljudstvo se je razšlo, vsakdo v hišo svojo.',
        20: 'Potem se David vrne, da blagoslovi hišo svojo. In Mihala, hči Savlova, mu pride naproti in reče: Kako častit je danes bil kralj Izraelov, ki se je danes razodeval pred deklami hlapcev svojih, kakor se nesramno razodevajo lahkomiselneži!',
        21: 'David pa reče Mihali: Igral sem pred Gospodom, ki me je izvolil mimo očeta tvojega in mimo vse hiše njegove, da me postavi za vojvodo ljudstvu Gospodovemu, Izraelu, in še bom igral pred Gospodom.',
        22: 'In še bolj se hočem ponižati in nizek biti v svojih očeh, a pri deklah, ki si o njih govorila, si s tem pridobim čast!',
        23: 'In Mihala, hči Savlova, ni dobila zaroda do dne smrti svoje.',
    },
    7: {
        1: 'In zgodi se, ko je prebival kralj v hiši svoji in mu je Gospod dal pokoj od vseh sovražnikov njegovih okoli,',
        2: 'da reče kralj Natanu proroku: Poglej zdaj, jaz stanujem v cedrovi hiši, skrinja Božja pa prebiva pod preprogami.',
        3: 'In Natan veli kralju: Pojdi, stóri vse, kar ti je v srcu, zakaj Gospod je s teboj.',
        4: 'A še to noč pride beseda Gospodova k Natanu, govoreč:',
        5: 'Pojdi in reci hlapcu mojemu, Davidu: Tako pravi Gospod: Ali mi boš ti zgradil hišo, da prebivam v njej?',
        6: 'Saj nisem prebival v hiši od dne, ko sem odpeljal sinove Izraelove iz Egipta, do današnjega dne, temuč sem hodil ž njimi v šatoru in prebivališču.',
        7: 'Kamorkoli sem šel z vsemi sinovi Izraelovimi, sem li kdaj besedo govoril s katerim rodov Izraelovih, ki sem jim zapovedal pasti ljudstvo moje, Izraela, rekoč: Zakaj mi niste zgradili cedrove hiše?',
        8: 'Tako torej véli hlapcu mojemu, Davidu: Tako pravi Gospod nad vojskami: Jaz sem te vzel s pašnikov, ko si hodil za ovcami, da bodeš vojvoda ljudstvu mojemu, Izraelu;',
        9: 'in sem bil s teboj, kamorkoli si šel, in sem zatrl vse sovražnike tvoje pred teboj in storil ti veliko ime, kakor ime velikašev, ki so na zemlji.',
        10: 'In hočem pripraviti mesto ljudstvu svojemu in jih posaditi, da bodo prebivali na svojem in se več ne premikali, da jih tudi ne bodo stiskali več sinovi krivice kakor poprej',
        11: 'in odkar sem zapovedal sodnikom, da naj bodo nad ljudstvom mojim, Izraelom. In dal sem ti pokoj pred vsemi sovražniki tvojimi. Vrhutega ti Gospod oznanja, da Gospod zgradi hišo tebi.',
        12: 'Ko se ti dopolnijo dnevi in boš ležal z očeti svojimi, hočem za tabo obuditi seme tvoje, ki pride iz osrčja tvojega, in utrditi kraljestvo njegovo.',
        13: 'On zgradi hišo imenu mojemu, in jaz utrdim kraljestva njegovega prestol na veke.',
        14: 'Jaz mu bodem za očeta, in on mi bode za sina. Kadar stori kaj krivega, ga bom pokoril s človeško šibo in kaznoval z udarci človečjih otrok.',
        15: 'Ali milost moja ne odstopi od njega, kakor sem jo odtegnil Savlu, ki sem ga odpravil izpred tebe.',
        16: 'Ampak hiša tvoja in kraljestvo tvoje bode stanovitno pred teboj vekomaj, prestol tvoj bodi utrjen na veke.',
        17: 'Po vseh teh besedah in po vsej tej prikazni je točno govoril Natan Davidu.',
        18: 'Tedaj stopi David noter in sede pred Gospoda in reče: Kdo sem jaz, o Gospod Jehova, in kaj je hiša moja, da si me privedel tako daleč?',
        19: 'In to se je še premalo videlo tvojim očem, o Gospod Jehova, kajti govoril si tudi o hlapca svojega hiši za daljno prihodnost, in to po načinu človeka, Gospod Jehova!',
        20: 'In kaj more David še govoriti tebi? Saj poznaš hlapca svojega, o Gospod Jehova!',
        21: 'Zaradi besede svoje in po srcu svojem si storil vso to velikost, oznanivši jo hlapcu svojemu.',
        22: 'Zategadelj si velik, o Jehova Bog! kajti ni ga tebi enakega, tudi ni Boga razen tebe, po vsem tem, kar smo slišali z ušesi svojimi.',
        23: 'In je li en narod na zemlji podoben ljudstvu tvojemu, Izraelu, ki je zaradi njega šel Bog, da ga odkupi sebi v ljudstvo ter si napravi veliko ime in stori take velike in strašne reči zanj in za deželo svojo, vpričo ljudstva svojega, ki si ga sebi odkupil iz Egipta, izpod oblasti narodov in njih bogov?',
        24: 'In pripravil si sebi ljudstvo svoje, Izraela, da ti bodi ljudstvo na veke, ti pa, Jehova, si postal njih Bog!',
        25: 'Sedaj pa, o Jehova Bog, potrdi na vekomaj besedo, ki si jo govoril za hlapca svojega in za hišo njegovo, in stori, kakor si govoril.',
        26: 'Da naj se poveličuje ime tvoje vekomaj in se govori: Gospod nad vojskami je Bog nad Izraelom. In hiša hlapca tvojega Davida bodi trdna pred teboj!',
        27: 'Zakaj ti, Gospod nad vojskami, Bog Izraelov, si razodel ušesu hlapca svojega, rekoč: Hišo ti hočem zgraditi. Zato se je hlapec tvoj osrčil, da moli to molitev tebi.',
        28: 'In sedaj, o Gospod Jehova, ti si Bog, in besede tvoje so resnica, in ti si govoril hlapcu svojemu to predobro obljubo:',
        29: 'sedaj torej rači blagosloviti hlapca svojega hišo, da ostane pred teboj vekomaj, zakaj ti, o Gospod Jehova, si to obljubil. Bodi torej z blagoslovom tvojim blagoslovljena tvojega hlapca hiša vekomaj!',
    },
    8: {
        1: 'In zgodi se potem, da je porazil David Filistejce in jih ponižal. In David je vzel uzdo vladarstva iz rok Filistejcev.',
        2: 'Porazil je tudi Moabce in jih premeril z vrvjo, ko jih je dal položiti na tla, in po dve vrvi jih je odmeril v smrt, po eno celo vrv pa, da žive. Tako so Moabci postali podložni Davidu in so mu prinašali darove.',
        3: 'David je tudi porazil Hadadezerja, sina Rehobovega, kralja v Zobi, ko je šel, da si spet pridobi oblast pri veletoku.',
        4: 'In David je iz njih ujel tisoč in sedemsto konjikov in dvajset tisoč pešcev ter je ohromil vse vprežne konje, ohranil jih je samo za sto voz.',
        5: 'A Sirci so prišli iz Damaska pomagat Hadadezerju, kralju v Zobi. David pa je pobil Sircev dvaindvajset tisoč mož',
        6: 'in postavil posadko v Sirijo ob Damasku; tako so postali Sirci Davidu podložni in so mu prinašali darove. Kajti Gospod je pomagal Davidu, kamorkoli je šel.',
        7: 'In David je vzel zlate ščite, ki so jih imeli hlapci Hadadezerjevi, in jih je prinesel v Jeruzalem.',
        8: 'In iz Betaha in iz Berotaja, mest Hadadezerjevih, je kralj David vzel mnogo brona.',
        9: 'In ko začuje Toj, kralj v Hamatu, da je David porazil vso vojsko Hadadezerjevo,',
        10: 'pošlje sina svojega Jorama h kralju Davidu, da ga pozdravi ter mu čestita, da se je bojeval zoper Hadadezerja in ga je porazil; zakaj Toj se je vedno vojskoval s Hadadezerjem. In Joram je prinesel s seboj srebrne, zlate in bronaste posode;',
        11: 'te je kralj David tudi posvetil Gospodu s srebrom in zlatom vred, ki ga je Gospodu posvetil od vseh narodov, kar si jih je bil podvrgel:',
        12: 'od Sircev, od Moabcev, od sinov Amonovih, od Filistejcev, od Amalekovcev in iz plena Hadadezerja sina Rehobovega, kralja v Zobi.',
        13: 'In David si je pridobil ime, ko se je vrnil, porazivši Sirce v Solni dolini, osemnajst tisoč mož.',
        14: 'In postavil je posadke v Edomu, po vsem Edomu je postavil posadke, in vsi Edomci so postali Davidovi podložniki. Kajti Gospod je pomagal Davidu, kamorkoli je šel.',
        15: 'In David je kraljeval vsemu Izraelu, in izvrševal je sodbo in pravičnost vsemu ljudstvu svojemu.',
        16: 'Joab pa, sin Zervijin, je bil nad vojsko, in Josafat, sin Ahiludov, je bil deželni letopisec;',
        17: 'Zadok, sin Ahitubov, in Ahimelek, sin Abiatarjev, sta bila duhovnika, in Seraja je bil pisar;',
        18: 'in Benaja, sin Jojadov, je bil nad Keretejci in Peletejci, in sinovi Davidovi so bili prvi dvorjani.',
    },
    9: {
        1: 'In David je dejal: Je li še kdo, ki je preostal iz hiše Savlove, da mu izkažem milost zaradi Jonatana?',
        2: 'Bil pa je hlapec iz hiše Savlove, po imenu Ziba; tega pokličejo k Davidu. In kralj ga vpraša: Si li ti Ziba? On reče: Da, hlapec tvoj je.',
        3: 'In kralj reče: Je li še kdo od hiše Savlove, da mu izkažem milost Božjo? Ziba odgovori kralju: Še je sin Jonatanov, hrom na nogah.',
        4: 'In kralj ga vpraša: Kje je? In Ziba reče kralju: Glej, on je v hiši Mahirja, sina Amielovega, v Lodebarju.',
        5: 'Nato pošlje kralj David in ga da pripeljati iz hiše Mahirja, sina Amielovega, iz Lodebarja.',
        6: 'In Mefiboset, sin Jonatana, sina Savlovega, pride k Davidu in pade na obraz in stori poklon. David pa reče: Mefiboset! On odgovori: Tu sem, hlapec tvoj.',
        7: 'In David mu reče: Ne boj se! zakaj gotovo ti hočem izkazati milost zaradi Jonatana, očeta tvojega, in povrnem ti vse njive Savla, očeta tvojega, in jedel boš kruh pri moji mizi vsak dan.',
        8: 'On se pokloni in reče: Kaj je hlapec tvoj da se oziraš na mrtvega psa, kakor sem jaz?',
        9: 'Tedaj pokliče kralj Ziba, Savlovega hlapca, in mu reče: Vse, kar je bilo Savlovega in vse njegove rodbine, sem dal sinu gospodarja tvojega.',
        10: 'Obdeluj torej zemljo njegovo zanj ti in sinovi in hlapci tvoji, in spravljaj pridelke, da bodo kruh sinu gospodarja tvojega, da se s tem živi; ali Mefiboset, gospodarja tvojega sin, bo vsak dan jedel kruh pri mizi moji. Imel pa je Ziba petnajst sinov in dvajset hlapcev.',
        11: 'Nato reče Ziba kralju: Po vsem, kar je zapovedal gospod moj, kralj, svojemu hlapcu, bo storil hlapec tvoj. Zastran Mefiboseta, veli kralj, ta bo jedel pri mizi kakor kraljevih otrok eden.',
        12: 'Mefiboset pa je imel majhnega sina, po imenu Miha. In vsi, ki so bivali v hiši Zibovi, so bili hlapci Mefibosetu.',
        13: 'In Mefiboset je prebival v Jeruzalemu, zakaj jedel je vsak dan pri kraljevi mizi. Bil pa je hrom na obeh nogah.',
    },
    10: {
        1: 'In zgodi se potem, da je umrl kralj Amonovih sinov, in Hanun, sin njegov, je zakraljeval na njegovem mestu.',
        2: 'In David reče: Milost izkažem Hanunu, sinu Nahasovemu, kakor je njegov oče izkazal milost meni. Pošlje torej David in mu sporoči po hlapcih svojih sožalje zaradi očeta njegovega. Ko so pa prišli hlapci Davidovi v deželo Amonovih sinov,',
        3: 'reko knezi Amonovcev Hanunu, gospodu svojemu: Meniš li, da David spoštuje očeta tvojega, ker je poslal tolažnike k tebi? Ni li poslal David hlapcev svojih, da ogleda mesto in ga preišče in potem razvrne?',
        4: 'Nato vzame Hanun hlapce Davidove in jim obrije polovico brade in odreže njih oblačil polovico do pasa, in jih pošlje nazaj.',
        5: 'Ko se to sporoči Davidu, jim pošlje naproti; zakaj ti možje so bili silno osramočeni. In kralj jim sporoči: Ostanite v Jerihu, dokler vam ne porasto brade, potem se vrnite.',
        6: 'In ko so videli sinovi Amonovi, da so se omrzili Davidu, pošljejo in najmejo Sirce iz Bet-rehoba in Sirce iz Zobe, dvajset tisoč pešcev, in kralja v Maaki s tisoč možmi in iz Toba dvanajst tisoč mož.',
        7: 'Ko pa David to sliši, pošlje Joaba in vso vojsko junakov.',
        8: 'In Amonovi sinovi gredo iz mesta in se pripravijo za boj ob vhodu v vrata. In Sirci iz Zobe in iz Rehoba in možje iz Toba in Maake so stali posebe na polju.',
        9: 'Ko torej Joab vidi, da je spredaj in zadaj naskok naperjen proti njemu, izbere iz vseh najboljših mož Izraelovih in se pripravi zoper Sirce.',
        10: 'Ostalo ljudstvo pa da pod roko brata svojega Abisaja, da jih postavi zoper Amonove sinove.',
        11: 'In veli: Ako mi bodo Sirci premočni, bodi mi v pomoč, ako bodo pa Amonovci tebi premočni, pridem ti v pomoč!',
        12: 'Bodi srčen, in junaški se bojujva za ljudstvo naše in za mesta Boga našega, in Gospod naj stori, kar se mu vidi dobro.',
        13: 'In Joab in ljudstvo, ki je bilo pri njem, se približa na boj zoper Sirce, in zbeže pred njim.',
        14: 'Ko pa vidijo Amonovi sinovi, da so bežali Sirci, zbeže tudi oni pred Abisajem in pridejo v svoje mesto. Tedaj se vrne Joab od Amonovcev in pride v Jeruzalem.',
        15: 'In ko vidijo Sirci, da so jih porazili Izraelci, se zbero.',
        16: 'In Hadarezer pošlje in veli pripeljati Sirce, ki so bili onostran reke, in pridejo v Helam s Sobahom, poveljnikom vojske Hadarezerjeve na čelu.',
        17: 'In to se oznani Davidu; in zbere vsega Izraela in preide Jordan in dospe v Helam. Sirci se pa pripravijo zoper Davida in se bojujejo ž njim.',
        18: 'A Sirci zbeže pred Davidom; in David je pobil iz Sircev mož od sedemsto voz in štirideset tisoč konjikov, udaril je tudi Sobaha, poveljnika njih vojske, da je ondi umrl.',
        19: 'In ko so videli vsi kralji, ki so bili v službi Hadarezerjevi, da so bili poraženi pred Izraelom, so sklenili mir z Izraelci in so jim bili podložni. In Sirci so se bali pomagati še dalje Amonovim sinovom.',
    },
    11: {
        1: 'In ko je preteklo leto, ob času, ko hodijo kralji ven na boj, pošlje David Joaba in hlapce svoje ž njim in vsega Izraela; in opustošili so deželo Amonovih sinov in oblegali Rabo. David pa je ostal v Jeruzalemu.',
        2: 'In zgodi se proti večeru, ko je vstal David iz postelje in se je izprehajal po strehi kraljeve hiše, da je videl s strehe ženo, ki se je kopala. Žena pa je bila silno lepega lica.',
        3: 'In David pošlje in vpraša po tisti ženi. In nekdo reče: Ni li Batseba, hči Eliamova, žena Urija Hetejca?',
        4: 'In David pošlje tja sle in jo da pripeljati. In pride k njemu, in on je spal pri njej. In ko se je očistila nečistote svoje, se vrne v hišo svojo.',
        5: 'In žena je spočela; in pošlje ter oznani Davidu, rekoč: Spočela sem.',
        6: 'In David sporoči Joabu: Pošlji mi Urija Hetejca! In Joab pošlje Urija k Davidu.',
        7: 'In ko pride Urija k njemu, ga vpraša David, kako se godi Joabu in ljudstvu ter kako napreduje vojska.',
        8: 'In David veli Uriju: Pojdi doli v hišo svojo in umij si noge! In Urija odide iz kraljeve hiše, in za njim pride kraljevo darilo.',
        9: 'Ali Urija je spal pred vrati kraljeve hiše z vsemi hlapci gospoda svojega in ni šel doli v hišo svojo.',
        10: 'In ko so povedali Davidu: Urija ni šel doli v hišo svojo, reče David Uriju: Nisi li prišel s pota? Zakaj nisi stopil doli v hišo svojo?',
        11: 'Urija pa odgovori Davidu: Skrinja in Izrael in Juda bivajo v šatorih, in Joab, gospod moj, in gospoda mojega hlapci tabore na polju, in jaz naj bi šel v hišo svojo, da jem in pijem in spim pri ženi svoji? Kakor res živiš in kakor živi duša tvoja, tega ne storim!',
        12: 'In David veli Uriju: Ostani tu še danes, jutri te odpošljem! Tako je ostal Urija v Jeruzalemu tisti in naslednji dan.',
        13: 'In David ga povabi, da bi jedel in pil pred njim, in ga upijani; ali on gre zvečer ven leč na ležišče svoje s hlapci gospoda svojega, in ni šel doli v hišo svojo.',
        14: 'Zjutraj pa napiše David list Joabu in ga pošlje po Uriju.',
        15: 'V list pa napiše takole: Postavite Urija prvega tja, kjer je bitka najhujša, in umeknite se od njega, da ga udarijo in umre.',
        16: 'Ko je torej Joab obkolil mesto, postavi Urija na mesto, za katero je vedel, da so tam junaški možje.',
        17: 'In možje planejo iz mesta in se bojujejo z Joabom, in padejo nekateri iz ljudstva, iz hlapcev Davidovih, tudi Urija Hetejec umrje.',
        18: 'Nato pošlje Joab in naznani Davidu vse, kar se je v boju prigodilo,',
        19: 'in zapove slu, rekoč: Ko kralju dopoveš vse, kar se je v boju zgodilo,',
        20: 'in boš videl, da se razsrdi in ti poreče: Zakaj ste tako blizu pristopili k mestu, da se bojujete? Niste li vedeli, da bodo z ozidja doli streljali?',
        21: 'Kdo je ubil Abimeleka, sina Jerub-besetovega? ni li vrgla žena zgornjega mlinskega kamena nanj z obzidja, da je umrl v Tebezu? Zakaj ste pristopili tako blizu zidovja? – tedaj reci: Hlapec tvoj, Urija Hetejec, je tudi mrtev.',
        22: 'Šel je torej sel, in pride in oznani Davidu vse, kar mu je sporočil Joab.',
        23: 'In reče sel Davidu: Možje so bili močnejši nego mi in so planili nad nas na polje, mi pa smo jih potisnili nazaj do vhoda v mestna vrata.',
        24: 'In strelci so streljali na hlapce tvoje z obzidja, da so umrli nekateri hlapcev kraljevih, in hlapec tvoj, Urija Hetejec, je tudi mrtev.',
        25: 'David reče slu: Reci Joabu: Naj se ti ne zdi prehuda ta reč, zakaj meč požre zdaj tega, zdaj onega; vztrajaj le v boju zoper mesto in ga razdeni! S tem ga ohrabri!',
        26: 'Ko pa je slišala žena Urijeva, da je umrl Urija, njen mož, je žalovala po svojem soprogu.',
        27: 'In ko je minilo žalovanje, pošlje David in jo vzame v hišo svojo, in je postala žena njegova in mu je rodila sina. Ali reč, ki jo je bil David storil, je bila huda v očeh Gospodovih.',
    },
    12: {
        1: 'In Gospod pošlje Natana k Davidu. In pride k njemu ter mu reče: Dva moža sta bila v enem mestu: eden bogat, drugi ubog.',
        2: 'Bogatin je imel silno veliko ovac in goved.',
        3: 'A ubožec ni imel ničesar razen edine drobne ovčice, ki si jo je bil kupil in zredil; in zrasla je pri njem ž njegovimi otroki vred: od njegovega grižljaja je jedla in iz njegovega kozarca je pila in njemu v naročju je spavala, in bila mu je kakor hči.',
        4: 'Pa pride popotnik k bogatinu, in temu se je žalilo vzeti iz ovac in goved svojih, da pripravi jed popotniku, ki je prišel k njemu, ampak vzame ubožcu ovčico ter jo pripravi možu, ki je dospel k njemu.',
        5: 'In Davidov srd se silno razvname zoper tistega moža, in veli Natanu: Kakor res Gospod živi, sin smrti je človek, ki je to storil;',
        6: 'tudi ovco mora povrniti četvero, ker je tako reč storil in ker se mu ni smililo.',
        7: 'Natan pa reče Davidu: Ti si tisti mož! Tako pravi Gospod, Bog Izraelov: Jaz sem te pomazilil za kralja nad Izraelom in jaz sem te otel iz roke Savlove,',
        8: 'in dal sem ti gospodarja tvojega hišo in gospodarja tvojega žene v naročje tvoje, in dal sem ti hišo Izraelovo in Judovo; in ako bi to bilo premalo, bi hotel pridejati še to in ono.',
        9: 'Zakaj si zaničeval besedo Gospodovo, da si storil, kar je hudo v očeh Gospodovih? Urija Hetejca si udaril z mečem in ženo njegovo sebi vzel za ženo, njega pa si umoril z mečem Amonovih sinov!',
        10: 'Sedaj torej ne odstopi meč od hiše tvoje nikdar, ker si me zaničeval in si vzel Uriju Hetejcu ženo, da bodi tvoja žena.',
        11: 'Tako pravi Gospod: Glej, hočem obuditi nesrečo zoper tebe iz hiše tvoje, in vzamem žene tvoje tebi pred očmi in jih dam bližnjemu tvojemu, da bo spal pri ženah tvojih pri svetlem solncu.',
        12: 'Ti si res to skrivaj storil, ali jaz to storim vpričo vsega Izraela, ob belem dnevu.',
        13: 'In David reče Natanu: Grešil sem zoper Gospoda. A Natan reče Davidu: Gospod je tudi odvzel greh tvoj, ne boš umrl.',
        14: 'Toda ker si s tem dejanjem dal priliko sovražnikom Gospodovim, da preklinjajo, zato tudi sin, ki se ti je rodil, gotovo umre.',
        15: 'In Natan odide domov. In Gospod udari otroka, ki ga je rodila žena Urijeva Davidu, in razboli se na smrt.',
        16: 'In David je iskal Boga zavoljo dečka in se je postil in prišel in ležal vso noč na tleh.',
        17: 'Tedaj vstanejo starejšine hiše njegove in stopijo okrog njega, da bi ga vzdignili s tal, ali on ni hotel, tudi ni jedel kruha ž njimi.',
        18: 'In zgodi se sedmi dan, da umrje dete. Bali so se pa hlapci Davidovi mu povedati, da je dete mrtvo, kajti dejali so: Glej, ko je dete še živelo, smo mu govorili, pa ni poslušal našega glasu; kako naj mu povemo, da je dete mrtvo? Lahko stori kaj hudega.',
        19: 'David pa, videč, da šepetajo med seboj hlapci njegovi, zazna, da je umrlo dete, in vpraša hlapce: Je li dete umrlo? Reko: Umrlo je.',
        20: 'Tedaj vstane David s tal in se umije in pomaže in preobleče, ter pride v hišo Gospodovo in moli. In ko se vrne domov, veli, naj mu prineso kruha, in jedel je.',
        21: 'Nato mu reko hlapci njegovi: Kaj je to, kar počenjaš? Ko je dete živelo, si se postil in plakal zanje, ko pa je dete mrtvo, si vstal in ješ kruh?',
        22: 'Odgovori: Dokler je dete še živelo, sem se postil in plakal, zakaj menil sem: Kdo ve, mi li ne bode Gospod milosten, da živo ostane dete?',
        23: 'Ali zdaj, ko je mrtvo, kaj bi se postil? Ga li morem v življenje povrniti? Jaz pač pojdem k njemu, a ono se ne vrne k meni.',
        24: 'In ko je David potolažil Batsebo, ženo svojo, je šel k njej in spal ž njo. In rodila je sina, tega je imenoval Salomona. In Gospod ga je ljubil,',
        25: 'in sporočil je po Natanu proroku, in on mu je dal ime Jedidija zaradi Gospoda.',
        26: 'Joab pa se je bojeval zoper Rabo sinov Amonovih in je zavzel kraljevo mesto.',
        27: 'In Joab pošlje sle k Davidu in sporoči: Bojeval sem se zoper Rabo in tudi zavzel Vodno mesto.',
        28: 'Sedaj pa zberi ostalo ljudstvo in oblezi mesto ter ga dobodi, da ga jaz ne dobim in se bo imenovalo po meni!',
        29: 'David torej zbere vse ljudstvo in gre proti Rabi in se bojuje zoper njo ter jo dobi.',
        30: 'In vzame krono njih kralja ž njegove glave, in njena teža je bila talent zlata in v njej so bili dragi kameni; in posadili so jo Davidu na glavo. Tudi plena iz mesta je odpeljal silno veliko.',
        31: 'Ljudstvo pa, ki je bilo v njem, je odpeljal in jih je postavil k žagam in k železnim strojem in k železnim sekiram ter jim je velel iti v opekarnice. Tako je storil vsem mestom Amonovih sinov. Potem se je vrnil David in vse ljudstvo v Jeruzalem.',
    },
    13: {
        1: 'Potem se zgodi, da je imel Absalom, sin Davidov, lepo sestro, po imenu Tamara, in Amnon, sin Davidov, se je zaljubil vanjo.',
        2: 'In Amnon je bil ves zbegan, da je obolel zaradi sestre svoje Tamare, kajti bila je devica, in Amnonu se je zdelo nemogoče, da bi ji kaj storil.',
        3: 'Imel pa je Amnon prijatelja, ki mu je bilo ime Jonadab, sin Simea, brata Davidovega; in Jonadab je bil jako prebrisan človek.',
        4: 'In mu reče: Zakaj, kraljev sin, medliš od dne do dne bolj? Mi li ne moreš povedati? In Amnon mu pove: Ljubim Tamaro, svojega brata Absaloma sestro.',
        5: 'In Jonadab mu reče: Lezi na posteljo in delaj se bolnega, in ko pride oče tvoj, da te pogleda, mu reci: Prosim, naj pride sestra moja Tamara, da mi da jesti in pripravi jed vpričo mene, da bom videl, in jedel bom iz roke njene.',
        6: 'Amnon torej leže in se naredi bolnega, in ko ga je prišel kralj pogledat, reče Amnon kralju: Prosim, naj pride sestra moja Tamara in mi pripravi dva kolača vpričo mene, da bi jedel iz roke njene.',
        7: 'Tedaj pošlje David domov po Tamaro, veleč: Pojdi, prosim, v brata svojega Amnona hišo in mu pripravi jed.',
        8: 'Tamara torej pride v hišo brata svojega Amnona, on pa je ležal. In ona vzame testo in ga ugnete in naredi kolačev pred njim in jih speče.',
        9: 'Potem vzame ponev in jih izsuje pred njega, ali on noče jesti. In Amnon veli: Spravite se vsi od mene ven! In ven so šli vsi od njega.',
        10: 'In Amnon reče Tamari: Prinesi jed v čumnato, da jem iz tvoje roke. In Tamara vzame kolače, ki jih je pripravila, in jih prinese v čumnato bratu svojemu Amnonu.',
        11: 'In ko mu jih poda, da bi jedel, jo zagrabi in ji reče: Pridi, lezi z menoj, sestra moja!',
        12: 'Ona mu pa odgovori: Ne, brat moj, nikar me ne sili, ker kaj takega se ne sme storiti v Izraelu. Ne stori te neumnosti!',
        13: 'Jaz pa, kam bi se obrnila s sramoto svojo? In ti bi bil kakor eden nespametnežev v Izraelu. Sedaj pa, prosim, govóri s kraljem, ta me ne odreče tebi.',
        14: 'Toda on ni hotel poslušati glasu njenega, in jo je premogel in posilil ter ležal pri njej.',
        15: 'Potem pa jo Amnon zasovraži s silno velikim sovraštvom, da je bilo sovraštvo, s katerim jo je sovražil, večje nego ljubezen, s katero jo je ljubil. In Amnon ji veli: Vstani, poberi se!',
        16: 'Ona pa mu reče: Nikar! to zlo, da me ženeš od sebe, je veliko hujše nego prvo, ki si mi ga storil. Ali on je ni hotel poslušati,',
        17: 'temuč pokliče dečka svojega, ki mu je stregel, in veli: Izženite to žensko od mene na ulico, in zakleni duri za njo!',
        18: 'Imela je pa pisano dolgo suknjo na sebi, zakaj tako so se oblačile kraljeve hčere, ki so bile device. Nato jo strežnik njegov odvede ven in zaklene duri za njo.',
        19: 'In Tamara si posuje s pepelom glavo in raztrga dolgo pisano oblačilo, ki ga je imela na sebi, in dene roke na glavo ter gre in gredé vpije.',
        20: 'In Absalom, njen brat, ji reče: Je li bil Amnon pri tebi, tvoj brat? Sedaj torej molči, sestra moja! Brat tvoj je on; ne žali srca svojega s tem! In Tamara je ostala zapuščena v hiši Absaloma, svojega brata.',
        21: 'Ko pa je kralj David slišal vse to, se je silno srdil.',
        22: 'In Absalom ni govoril z Amnonom ne dobrega, ne hudega, zakaj sovražil je Amnona, ker je bil posilil sestro njegovo Tamaro.',
        23: 'In ko sta minili dve leti, so strigli Absalomu ovce v Baal-hazorju, ki je pri Efraimu, in Absalom je povabil vse sinove kraljeve.',
        24: 'In Absalom gre h kralju in reče: Glej, hlapec tvoj striže ovce. Prosim, da bi šel kralj in njegovi hlapci s tvojim hlapcem.',
        25: 'Kralj pa reče Absalomu: Nikar, sin moj, ne zahtevaj, naj gremo vsi, da ti ne bomo nadležni. In dasi ga je silil, vendar ni hotel iti; in ga je blagoslovil.',
        26: 'Tedaj reče Absalom: Če ne, sme li brat moj Amnon iti z nami? In kralj ga vpraša: Čemu bi šel s teboj!',
        27: 'A ker ga je silil, dovoli Amnonu in vsem sinovom kraljevim iti ž njim.',
        28: 'Absalom pa zapove hlapcem svojim, rekoč: Pazite! Ko bo srce Amnonovo dobre volje od vina in ko vam povelim: Udarite Amnona! tedaj ga ubijte, ne bojte se; nisem li vam jaz zapovedal? Srčni bodite in hrabri!',
        29: 'In hlapci Absalomovi so storili Amnonu, kakor jim je bil Absalom zapovedal. Tedaj vstanejo vsi kraljevi sinovi in sedejo vsak na svojega mezga ter zbeže.',
        30: 'In ko so še bili na poti, pride vest Davidu, da pravijo: Pobil je Absalom vse sinove kraljeve, niti eden iz njih ni ostal.',
        31: 'Tedaj vstane kralj in raztrga oblačila svoja in leže na tla, in vsi hlapci njegovi stoje okoli z raztrganimi oblačili.',
        32: 'In Jonadab, sin Simea, brata Davidovega, izpregovori ter reče: Gospod moj, ne meni, da so pobili vse mladeniče, kraljeve sinove, zakaj Amnon sam je mrtev; to je namreč bilo na ustih Absalomovih, določeno od dne, ko je Amnon posilil Tamaro, sestro njegovo.',
        33: 'Zdaj torej naj s tem ne žali gospod moj, kralj, srca svojega, meneč, da so vsi kraljevi sinovi mrtvi, kajti edini Amnon je mrtev.',
        34: 'Absalom pa je zbežal. In mladenič, ki je bil na straži, povzdigne oči ter vidi, in glej: mnogo ljudstva prihaja po poti ob hribu, vzadaj za njim.',
        35: 'In Jonadab reče kralju: Glej, kraljevi sinovi prihajajo! Kakor je rekel hlapec tvoj, tako je.',
        36: 'In ko izgovori, pridejo kraljevi sinovi in povzdignejo glas svoj in zaplakajo; tudi kralj in vsi hlapci njegovi jokajo zelo bridko.',
        37: 'Absalom pa je zbežal in šel k Talmaju, sinu Amihurjevemu, kralju v Gesurju. In David je žaloval po svojem sinu vse dni.',
        38: 'Absalom je torej zbežal in šel v Gesur in je bil ondi tri leta.',
        39: 'In kralj David si je želel iti tja k Absalomu, zakaj utolažil se je bil zaradi Amnona, ker je bil mrtev.',
    },
    14: {
        1: 'Joab pa, sin Zervijin, je zaznal, da se je srce kraljevo nagnilo k Absalomu.',
        2: 'In pošlje Joab v Tekoo ter da pripeljati odondod modro ženo in ji veli: Delaj se, prosim, žalujočo in obleci žalno obleko in ne pomaži se z oljem, temuč bodi kakor žena, ki je že dolgo časa žalovala po mrtvem.',
        3: 'Potem pojdi h kralju ter govóri na ta način ž njim! In Joab jo je poučil, kaj naj govori.',
        4: 'In ko žena iz Tekoe ogovori kralja, pade z obrazom na tla ter stori poklon in reče: Pomagaj mi, o kralj!',
        5: 'In kralj jo vpraša: Kaj ti je? In odgovori: Resnično, vdova sem, ker moj mož je mrtev.',
        6: 'In dekla tvoja je imela dva sinova, in ta sta se med sabo sprla na polju, in ker ga ni bilo, ki bi bil branil, je udaril brat brata in ga ubil.',
        7: 'In glej, vsa rodovina je vstala zoper deklo tvojo in pravijo: Daj sem tistega, ki je ubil brata svojega, da ga usmrtimo za dušo brata, ki ga je umoril, in uničimo tudi dediča! Tako hočejo ugasiti mojo iskro, ki je preostala, da ne ostane možu mojemu ne imena, ne potomca na zemlji.',
        8: 'Kralj pa veli ženi: Pojdi domov, in zapovem zate!',
        9: 'A žena iz Tekoe reče kralju: Gospod moj, kralj, na meni bodi ta pregreha in na mojega očeta hiši, kralj pa in prestol njegov bodi nedolžen!',
        10: 'In kralj reče: Kdorkoli govori kaj zoper tebe, tega pripelji k meni, in ne sme se te več dotekniti.',
        11: 'Ona reče: Naj se kralj spomni, prosim, Gospoda, Boga svojega, da ne napravi krvni maščevalec še več pogube in ne iztrebijo sina mojega. On veli: Kakor res Gospod živi, še las ne pade sinu tvojemu na zemljo!',
        12: 'Nato reče žena: Pove naj, prosim, dekla tvoja besedo gospodu svojemu, kralju. On veli: Govóri!',
        13: 'In žena reče: Zakaj si kaj takega mislil zoper ljudstvo Božje? Kajti s tem, kar je kralj rekel, se je sam obdolžil, ker noče kralj pripeljati domov izgnanca svojega.',
        14: 'Zakaj gotovo umremo vsi in smo kakor voda, razlita po zemlji, ki se ne more več zbrati; tudi Bog ne jemlje življenja, ampak snuje načrte, da ne ostane tisti, ki je izgnan, izgnan od njega.',
        15: 'Da sem pa prišla govorit to gospodu svojemu, kralju, zgodilo se je, ker me je ljudstvo strašilo; in dekla tvoja je mislila: Govorila bom vsaj s kraljem, morebiti izpolni kralj prošnjo svoje dekle.',
        16: 'Kajti kralj usliši deklo svojo, da me otme iz roke moža, ki hoče zatreti mene in sina mojega z menoj iz dediščine Božje.',
        17: 'Zato si je rekla dekla tvoja: Beseda gospoda mojega, kralja, mi bodi v pomirjenje; zakaj kakor angel Božji je gospod moj, kralj, da razpozna dobro in hudo. In Gospod Bog tvoj bodi s teboj.',
        18: 'Tedaj odgovori kralj in reče ženi: Ne taji mi, prosim, kar te bom vprašal. In žena reče: Govori naj, prosim, gospod moj, kralj.',
        19: 'Kralj pa vpraša: Ni li roka Joabova s teboj v vsem tem? In žena odgovori ter reče: Kakor res živi duša tvoja, gospod moj, kralj, ni ga človeka ne na desnici, ne na levici razen onega, ki ga je imenoval gospod moj, kralj: zakaj hlapec tvoj Joab mi je zapovedal in je položil vse te besede v usta dekle tvoje.',
        20: 'Da se obrne lice te stvari, je hlapec tvoj Joab storil to; a gospod moj je moder, kakor je modrost angela Božjega, da zna za vse, kar se godi na zemlji.',
        21: 'In kralj veli Joabu: Glej torej, storil sem to reč; zato pojdi in pripelji mladeniča Absaloma nazaj!',
        22: 'In Joab pade z obrazom na tla in stori poklon in blagoslovi kralja in reče: Danes je spoznal hlapec tvoj, da sem našel milost v tvojih očeh, gospod moj, kralj, v tem, da je kralj izpolnil prošnjo hlapca svojega.',
        23: 'In vstane Joab in odide v Gesur in pripelje Absaloma v Jeruzalem.',
        24: 'Kralj pa veli: Naj krene v hišo svojo, a mojega obličja naj ne vidi! In Absalom je krenil v hišo svojo, a kraljevega obličja ni videl.',
        25: 'V vsem Izraelu pa ga ni bilo moža, ki bi se smel hvaliti zaradi lepote kakor Absalom: od stopala do temena ni bilo hibe na njem.',
        26: 'In kadar si je dal striči glavo (to se je zgodilo vsako leto; ker so mu bili lasje pretežki, so jo morali striči), so tehtali lasje njegove glave dvesto seklov, po kraljevi tehtnici.',
        27: 'In Absalomu so se rodili trije sinovi in ena hči, po imenu Tamara: ta je bila žena lepe postave.',
        28: 'In Absalom je prebival v Jeruzalemu dve celi leti in ni videl kraljevega obličja.',
        29: 'Tedaj pošlje Absalom po Joaba, da bi ga poslal h kralju, a ni hotel priti k njemu; in pošlje še enkrat, a ni hotel priti.',
        30: 'Zatorej reče hlapcem svojim: Glejte, Joabova njiva je poleg moje in raste ječmen na njej: pojdite in jo zažgite. In Absalomovi hlapci so požgali njivo.',
        31: 'Nato vstane Joab in pride na dom k Absalomu ter mu reče: Zakaj so požgali hlapci tvoji mojo njivo?',
        32: 'In Absalom odgovori Joabu: Glej, poslal sem k tebi, veleč: Pridi sem, da te pošljem h kralju sporočit: Čemu sem prišel iz Gesurja? Bolje bi mi bilo, da bi bil še tam. Zdaj torej poskrbi, da vidim obličje kraljevo; ako je pa krivica na meni, naj me umori!',
        33: 'Joab torej stopi h kralju in mu to pove. In ko ga pokliče, pride Absalom h kralju in se mu pokloni z obrazom do tal, in kralj poljubi Absaloma.',
    },
    15: {
        1: 'A potem se zgodi, da si oskrbi Absalom voz in konj in petdeset mož, da bi tekali pred njim.',
        2: 'In Absalom je vstajal zgodaj in postajal pri poti v vrata, in kadar je kdo imel pravdo, ki je imela priti pred kralja v razsodbo, ga je Absalom poklical k sebi in vprašal: Iz katerega mesta si? In odgovori: Hlapec tvoj je iz enega rodov Izraelovih.',
        3: 'Absalom mu pa reče: Glej, tvoja stvar je dobra in pravična; a ni ga postavljenega od kralja, ki bi te zaslišal.',
        4: 'Tudi je Absalom dejal: O da bi me postavili za sodnika v deželi, da pride k meni vsak, kdor ima pravdo ali tožbo, in jaz bi mu poskrbel za pravico!',
        5: 'In če je kdo pristopil, da mu stori poklon, je iztegnil svojo roko ter ga zadržal in ga poljubil.',
        6: 'In na ta način je delal Absalom vsem Izraelcem, ki so prihajali h kralju na sodbo, in tako je kradel zase srca mož Izraelovih.',
        7: 'In ko se mu je končalo štirideseto leto, reče Absalom kralju: Prosim, naj grem v Hebron in izvršim obljubo svojo, ki sem jo storil Gospodu.',
        8: 'Hlapec tvoj je namreč storil obljubo, ko je bival v Gesurju v Siriji, rekši: Ako me Gospod res pripelje spet v Jeruzalem, storim službo Gospodu.',
        9: 'In kralj mu veli: Pojdi v miru! Vstane torej in gre v Hebron.',
        10: 'Poslal pa je bil Absalom oglednike po vseh rodovih Izraelovih s poveljem: Kadar začujete trombe glas, recite: Zakraljeval je Absalom v Hebronu!',
        11: 'Z Absalomom pa je šlo iz Jeruzalema dvesto mož, ki so bili povabljeni in so šli v nedolžnosti svoji, ne da bi bili kaj vedeli za to reč.',
        12: 'In Absalom pošlje po Ahitofela Gilonskega, svetnika Davidovega, naj pride iz mesta svojega, iz Gila, ko je klal daritve. In zarota se je jačila, ker se je ljudstvo bolj in bolj množilo pri Absalomu.',
        13: 'V tem pride glasnik in sporoči Davidu: Srce mož Izraelovih se je vdalo Absalomu.',
        14: 'In David reče vsem hlapcem svojim, ki so bili pri njem v Jeruzalemu: Vstanite, bežímo! sicer nam ne bo rešitve pred Absalomom. Hitite, da gremo, da nas ne prenagli in dohiti in spravi nesrečo nad nas in udari mesto z ostrino meča.',
        15: 'In kraljevi hlapci mu reko: Glej, hlapci tvoji store, karkoli izvoli gospod moj, kralj.',
        16: 'In kralj gre iz mesta in vsa družina njegova za njim; samo deset žen, priležnic, je pustil doma, naj čuvajo hišo.',
        17: 'Gre torej kralj iz mesta in vse ljudstvo peš za njim, in ustavijo se pri Skrajni hiši.',
        18: 'In vsi hlapci njegovi so šli mimo njega, tudi vsi Keretejci in Peletejci in vsi Gatovci, šeststo mož, ki so bili prišli v spremstvu njegovem iz Gata, so šli pred obličjem kraljevim.',
        19: 'Tedaj reče kralj Itaju Gatovcu: Čemu greš tudi ti z nami? Vrni se in ostani pri kralju! Zakaj tujec si, pa tudi prognanec; vrni se v svoj kraj!',
        20: 'Šele včeraj si prišel, in danes že naj bi te pustil hoditi semtertja z nami, ker moram iti kamorkoli. Vrni se in pelji nazaj brate svoje; milost in resnica bodi s teboj!',
        21: 'A Itaj odgovori kralju in reče: Kakor res Gospod živi in kakor živi gospod moj, kralj, gotovo, kjerkoli bode gospod moj, kralj, najsi gre za smrt ali za življenje, tam bode tudi hlapec tvoj!',
        22: 'In David veli Itaju: Pridi in pojdi naprej! Šel je torej Itaj Gatovec naprej in vsi možje njegovi in vsi otročiči, ki so bili ž njim.',
        23: 'In vsa dežela je jokala z velikim glasom, in vse ljudstvo je šlo čez potok. In kralj preide čez potok Kidron, tudi vse ljudstvo preide, proti potu v puščavo.',
        24: 'In glej, Zadok je tudi prišel in vsi leviti ž njim, nesoč skrinjo zaveze Božje; in postavili so skrinjo Božjo, in Abiatar je šel gori, dokler ni prešlo vse ljudstvo, kar ga je šlo iz mesta.',
        25: 'Kralj pa veli Zadoku: Nesi skrinjo Božjo nazaj v mesto! Ako najdem milost v očeh Gospodovih, me privede nazaj in mi jo zopet da videti in njeno prebivališče;',
        26: 'ako mi pa poreče takole: Nisi mi po volji – glej, tu sem, naj stori z mano, kakor se mu vidi prav.',
        27: 'Še reče kralj Zadoku duhovniku: Nisi li videc? Vrni se v mesto v miru in dva sinova tvoja s teboj, Ahimaaz, sin tvoj, in Jonatan, sin Abiatarjev.',
        28: 'Glej, počakam pri brodih ob puščavi, da pride vest od vas in mi sporočite.',
        29: 'Zadok torej in Abiatar sta zopet odnesla skrinjo Božjo v Jeruzalem, in ostala sta tam.',
        30: 'David pa je šel gori po pobočju Oljske gore in je grede jokal, in glavo je imel pokrito in je šel bos; in vse ljudstvo, ki je bilo pri njem, je šlo gori s pokritimi glavami in je gredoč jokalo.',
        31: 'In nekdo oznani Davidu, rekoč: Ahitofel je med zarotniki z Absalomom. David pa reče: O Gospod, prosim, obrni svet Ahitofelov v neumnost!',
        32: 'In zgodi se, ko dospe David na vrh, kjer so molili Boga, glej, Husaj Arkičan mu pride naproti in suknjo je imel raztrgano in glavo posuto s prstjo.',
        33: 'In David mu reče: Ako pojdeš z menoj, mi bodeš v težavo;',
        34: 'ako se pa povrneš v mesto in porečeš Absalomu: Hlapec tvoj hočem biti, o kralj; kakor sem bil doslej očeta tvojega hlapec, bodem zdaj tvoj hlapec, ovržeš meni v prid svet Ahitofelov.',
        35: 'Ne bodeta li tam s teboj Zadok in Abiatar, duhovnika? Zatorej, karkoli začuješ iz hiše kraljeve, naznani Zadoku in Abiatarju, duhovnikoma!',
        36: 'Glej, imata ondi pri sebi dva svoja sinova, Ahimaaza Zadokovega in Jonatana Abiatarjevega: po njiju mi sporočite, karkoli boste slišali.',
        37: 'Odide torej Husaj, prijatelj Davidov, v mesto. In Absalom je prišel v Jeruzalem.',
    },
    16: {
        1: 'In ko je David postopil malo dalje od vrha, glej, Ziba, hlapec Mefibosetov, mu pride naproti z dvema osedlanima osloma in na njiju pelje dvesto hlebov kruha in sto gruč suhih grozdov in stotino posušenih sadov in meh vina.',
        2: 'In kralj vpraša Ziba: Kaj hočeš s tem? In Ziba reče: Osla sta za kraljevo družino, da bo na njiju jezdila, kruh pa in sadje za jed mladeničem, in vino, da bodo pili tisti, ki opešajo v puščavi.',
        3: 'In kralj vpraša: Kje pa je tvojega gospodarja sin? In Ziba reče kralju: Glej, ostal je v Jeruzalemu; zakaj dejal je: Danes mi povrne hiša Izraelova mojega očeta kraljestvo.',
        4: 'Nato veli kralj Zibu: Glej, vse, kar ima Mefiboset, bodi tvoje! In Ziba reče: Poklanjam se! Da najdem milost v tvojih očeh, gospod moj, kralj!',
        5: 'In ko pride kralj David v Bahurim, glej, izide odondod mož iz rodovine hiše Savlove, po imenu Simej, sin Gerov; izide in grede preklinja.',
        6: 'In kamene je lučal na Davida in na vse hlapce kralja Davida; in vse ljudstvo Davidovo in vsi junaki so mu bili ob desnici in ob levici.',
        7: 'In tako je govoril Simej, ko je preklinjal: Pojdi, pojdi, krvoločnik in mož Belijalov!',
        8: 'Gospod ti je povrnil vso kri hiše Savlove, na čigar mestu si zakraljeval, in Gospod je dal kraljestvo v roko Absalomu, sinu tvojemu, in glej, tičiš v nesreči svoji, ker si krvoločnik.',
        9: 'Tedaj reče Abisaj, sin Zervijin, kralju: Zakaj bi smel ta mrtvi pes preklinjati gospoda mojega, kralja? Dovoli, da stopim tja in mu odsekam glavo!',
        10: 'Kralj pa reče: Kaj imam z vama opraviti, sinova Zervijina? Ko preklinja in ko mu je rekel Gospod: Prekolni Davida! kdo pa sme reči: Zakaj tako delaš?',
        11: 'še reče David Abisaju in vsem hlapcem svojim: Poglej, sin moj, ki je prišel iz osrčja mojega, mi streže po življenju, koliko bolj ta Benjaminec! Pustite ga, naj kolne; zakaj Gospod mu je velel.',
        12: 'Morda pogleda Gospod mojo revo in mi poplača Gospod z dobrim za to, da me kolne danes.',
        13: 'Tako je šel David svojim potom z ljudmi svojimi; Simej pa je šel ob strani gore njemu nasproti in je grede preklinjal in lučal kamene na Davida in metal prah.',
        14: 'Ko pa je kralj in ves ljud, ki je bil pri njem, dospel utrujen tja, se je okrepčal ondi.',
        15: 'Absalom pa in vse ljudstvo, vsi možje Izraelovi, so bili prišli v Jeruzalem, in Ahitofel ž njim.',
        16: 'In ko pride Husaj Arkičan, prijatelj Davidov, k Absalomu, reče Absalomu: Živel kralj! Živel kralj!',
        17: 'Absalom pa reče Husaju: To li je milost tvoja s prijateljem tvojim? Zakaj nisi šel s prijateljem svojim?',
        18: 'Husaj pa odgovori Absalomu: Nikar, temuč kogar je izvolil Gospod in to ljudstvo in vsi možje Izraelovi, njegov bodem in pri njem ostanem!',
        19: 'In drugič, komu naj bi služil? Ne li pred obličjem sinu njegovega? Kakor sem bil sluga pred očetom tvojim, tako bodem pred teboj.',
        20: 'In Absalom veli Ahitofelu: Svetuj, kaj nam je storiti?',
        21: 'Ahitofel reče Absalomu: Pojdi k priležnicam očeta svojega, ki jih je pustil, da čuvajo hišo; tako bo ves Izrael slišal, da si se omrzil očetu svojemu, in bodo roke vseh, ki so pri tebi, tem močnejše.',
        22: 'Nato razpno Absalomu šator na strehi, in Absalom je šel k priležnicam očeta svojega pred očmi vsega Izraela.',
        23: 'Svet Ahitofelov pa, ki ga je dajal v tistem času, je bil, kakor da bi kdo vprašal besedo Božjo: tako se je štelo vse svetovanje Ahitofelovo i pri Davidu i pri Absalomu.',
    },
    17: {
        1: 'Dalje reče Ahitofel Absalomu: Dovoli, da si izberem dvanajst tisoč mož in vstanem ter hitim za Davidom še nocoj.',
        2: 'In planem nanj, dokler je truden in slab, ter ga prestrašim; in ko vse ljudstvo, ki je pri njem, zbeži, udarim kralja samega,',
        3: 'vse ljudstvo pa pripeljem nazaj k tebi. Ko pogine mož, ki ga iščeš, se vsi povrnejo k tebi, in pride vsemu ljudstvu mir.',
        4: 'To se je zdelo dobro Absalomu in vsem starejšinam Izraelovim.',
        5: 'Tedaj reče Absalom: Pokliči, prosim, še Husaja Arkičana, in zaslišimo, kaj on pravi.',
        6: 'Ko pride Husaj k Absalomu, mu pove Absalom, rekoč: Tako in tako je svetoval Ahitofel. Ali naj storimo po besedah njegovih? Ako ne, govóri ti!',
        7: 'In Husaj reče Absalomu: Ni dober svet, ki ga je dal Ahitofel takrat.',
        8: 'Še reče Husaj: Poznaš očeta svojega in ljudi njegove, da so junaki in srdite narave kakor medvedka na polju, ko so ji mladiče vzeli; oče tvoj je tudi vojščak in ne bo nočeval pri ljudstvu.',
        9: 'Glej, lahko se je skril v kako jamo ali kam drugam; in ako se zgodi, da padejo nekateri iz njih kar s početka, kdorkoli zasliši, poreče: Poboj je bil med ljudstvom, ki je šlo za Absalomom.',
        10: 'Tako pa upade srce vsakomur, tudi če je kdo sicer hraber in ima srce kakor lev; zakaj ves Izrael ve, da je junak oče tvoj in tisti, ki so pri njem, da so vrli vojščaki.',
        11: 'Ali jaz svetujem, da spraviš k sebi vsega Izraela od Dana do Bersebe, ki ga je po množini kakor peska ob morju, in ti sam pojdi v boj.',
        12: 'In tako ga naskočimo v kakem kraju, kjer ga zalotimo, in ga zalezemo, kakor rosa pade na zemljo, da ne preostane od njega in od vseh njegovih niti eden mož.',
        13: 'Ako pa bi se umaknil v kako mesto, naj ves Izrael potegne vrvi okrog tistega mesta in ga povlečemo v potok, da se ne najde ne kamenček od njega.',
        14: 'Tedaj reko Absalom in vsi možje Izraelovi: Svet Husaja Arkičana je boljši nego svet Ahitofelov. Zakaj Gospod je tako obrnil, da je bil ovržen dobri svet Ahitofelov, zato, da spravi Gospod nesrečo nad Absaloma.',
        15: 'Husaj pa reče Zadoku in Abiatarju, duhovnikoma: Tako in tako je svetoval Ahitofel Absalomu in starejšinam Izraelovim, in takole sem svetoval jaz.',
        16: 'Zatorej pošljita hitro k Davidu in mu sporočita: Ne ostani to noč pri brodih ob puščavi, temuč vsekakor pojdi na ono stran, da ne bo požrt kralj z ljudstvom, ki je pri njem.',
        17: 'Jonatan pa in Ahimaaz sta stala pri studencu Rogelu, in dekla je hodila in jima poročala; zakaj nista se smela prikazati, da hodita v mesto. In šla sta ter oznanila kralju Davidu.',
        18: 'A neki deček ju zagleda in pove Absalomu; odideta torej hitro in stopita v hišo nekega moža v Bahurimu, ki je imel vodnjak na dvorišču; in spustita se vanj.',
        19: 'In žena vzame odejo in jo razgrne čez vodnjakovo odprtino in jo posuje z raztolčenim žitom, da se nič ne spozna.',
        20: 'Ko pa pridejo Absalomovi hlapci k ženi v hišo in vprašajo: Kje sta Ahimaaz in Jonatan? odgovori žena: Šla sta čez potoček! In ju iščejo; ko pa ju ne morejo najti, se vrnejo v Jeruzalem.',
        21: 'In ko so odšli, stopita onadva gori iz vodnjaka ter gresta in naznanita kralju Davidu in mu rečeta: Vstanite, hitro pojdite čez vodo; kajti tako je svetoval zoper vas Ahitofel.',
        22: 'Tedaj vstane David in vse ljudstvo, ki je bilo pri njem, in prebredejo Jordan. Ko se je zjutraj svitalo, niso pogrešili ne enega, ki bi ne bil prišel čez Jordan.',
        23: 'Ko pa je videl Ahitofel, da ne delajo, kakor je bil svetoval, osedla osla ter vstane in odide domov v mesto svoje in uredi hišo svojo ter se obesi, in je umrl in je bil pokopan v grobu očeta svojega.',
        24: 'David pa je dospel v Mahanaim. In Absalom je šel čez Jordan, on in vsi možje Izraelovi ž njim.',
        25: 'In Absalom je postavil Amasa nad vojsko namesto Joaba. Bil pa je Amasa sin moža, čigar ime je bilo Jitra Izraelit, ki je bil šel k Abigaili, hčeri Nahasovi, sestri Zervije, matere Joabove.',
        26: 'Izrael z Absalomom pa se je utaboril v Gileadski deželi.',
        27: 'In ko je David prišel v Mahanaim, so prinesli Sobi, sin Nahasov iz Rabe sinov Amonovih, in Mahir, sin Amielov iz Lodebarja, in Barzilaj Gileadčan iz Rogelima',
        28: 'postelje, medenice, lončene posode, pšenice, ječmena, moke, opraženega zrnja, boba, leče, praže,',
        29: 'medu, masla, ovac in sira za živež Davidu in ljudstvu, ki je bilo pri njem; zakaj dejali so: Ljudstvo je lačno, trudno in žejno v puščavi.',
    },
    18: {
        1: 'David pa sešteje ljudstvo, ki je bilo pri njem, in mu postavi poveljnike nad tisoč in poveljnike nad sto.',
        2: 'In David odpošlje ljudstvo, tretjino pod roko Joabovo, tretjino pod roko Abisaja, sina Zervije, brata Joabovega, in tretjino pod roko Itaja Gatovca. In kralj reče ljudstvu: Tudi jaz pojdem vsekakor z vami!',
        3: 'A ljudstvo reče: Ne pojdeš! Zakaj če pobegnemo, jim ne bode mar za nas; tudi če nas polovica pogine, ne bodo marali za nas; temuč ti si kakor nas deset tisoč. Zatorej je bolje, da boš pripravljen priskočiti nam v pomoč iz mesta.',
        4: 'Kralj jim reče: Kar se vam zdi najboljše, storim. In kralj se ustopi pri vratih, in vse ljudstvo gre ven po sto in po tisoč.',
        5: 'In kralj zapove Joabu in Abisaju in Itaju, rekoč: Milo mi ravnajte z mladeničem, z Absalomom! In vse ljudstvo je slišalo, ko je kralj zapovedoval vsem poveljnikom za Absaloma.',
        6: 'Šlo je torej ljudstvo na polje v boj proti Izraelu, in bitka se je začela v Efraimskem gozdu.',
        7: 'In ljudstvo Izraelovo je bilo ondi poraženo pred hlapci Davidovimi, in bil je tam velik poboj tisti dan, ker je padlo dvajset tisoč mož.',
        8: 'Zakaj boj se je ondi razširil po vsej deželi, in gozd je požrl več ljudstva tisti dan, nego jih je pobil meč.',
        9: 'Primeri se pa, da sreča Absalom hlapce Davidove. In Absalom je jezdil na mezgu svojem, in mezg je prišel pod debele veje košatega hrasta, in Absalomu je obtičala glava na hrastu, da je visel med nebom in zemljo, kajti mezg je izpod njega zdirjal.',
        10: 'In neki mož vidi to in oznani Joabu in reče: Glej, videl sem Absaloma, da visi na hrastu.',
        11: 'Joab pa veli možu, ki mu je povedal: Glej, ako si ga videl, zakaj ga nisi ondi pobil na zemljo? In jaz bi ti bil dal deset srebrnikov in pas.',
        12: 'Mož pa odvrne Joabu: Da si mi odštel tisoč srebrnikov na roko, ne bi bil hotel iztegniti roke zoper sina kraljevega; zakaj kralj je pred našimi ušesi zapovedal tebi in Abisaju in Itaju, rekoč: Pazite, da se nihče ne dotakne mladeniča Absaloma!',
        13: 'Sicer pa, ako bi bil storil kaj žalega zoper življenje njegovo (kajti nič ne ostane kralju skrito), ti sam bi stal zoper mene.',
        14: 'Nato reče Joab: Ne bom tu časa tratil s teboj! In vzame tri sulice v roko in jih zasadi Absalomu v srce, ko je še živel viseč na hrastu.',
        15: 'In deset mladeničev, oprod Joabovih, stopi okoli Absaloma in ga bijejo in umore.',
        16: 'In Joab zatrobi v trobento, in ljudstvo se vrne, da ne podi več Izraela; zakaj Joab je zadržal ljudstvo.',
        17: 'In vzamejo Absaloma ter ga vržejo v veliko jamo v gozdu in nanosijo nanj velik kup kamenja. In ves Izrael je bežal, vsak v šator svoj.',
        18: 'Absalom pa si je bil še za življenja svojega oskrbel in postavil spomenik, ki je v Kraljevi dolini; zakaj dejal je: Nimam sina, da se ohrani imena mojega spomin! In imenoval je tisti spomenik z imenom svojim, in imenuje se Absalomov spomenik do današnjega dne.',
        19: 'Ahimaaz pa, sin Zadokov, reče: Dovoli, da tečem in sporočim kralju, da mu je Gospod storil pravico in ga otel iz roke njegovih sovražnikov.',
        20: 'A Joab mu veli: Danes nisi poročevalec dobrega! Drugi dan lahko sporočiš blago vest, a danes nimaš kaj dobrega oznaniti, ker je kraljev sin mrtev.',
        21: 'Potem veli Joab Kušitu: Pojdi, povej kralju, kar si videl! In Kušit se prikloni Joabu in teče.',
        22: 'Tedaj reče Ahimaaz, sin Zadokov, zopet Joabu: Bodisi kakorkoli, dovoli, da tečem tudi jaz za Kušitom! Joab pa reče: Čemu hočeš tja teči, sin moj! Saj nimaš poročila, ki bi zanje dobil pohvalo.',
        23: 'On reče: Bodisi kakorkoli, potečem! In mu veli: Teci! In teče Ahimaaz po ravnini in prehiti Kušita.',
        24: 'David pa je sedel med dvojimi vrati. In stražar stopi na streho od vrat, na obzidju, povzdigne oči in gleda; in glej, mož teče sam.',
        25: 'In stražar zakliče in oznani kralju. Kralj pa reče: Ako je sam, je dobro oznanilo v njegovih ustih. Ko pa ta prihaja bliže in bliže,',
        26: 'zagleda stražar drugega moža tekočega, in zakliče vratarju in reče: Glej, mož teče sam! Kralj pa veli: Tudi ta ima dobro oznanilo.',
        27: 'In stražar reče: Zdi se mi, da tek prvega je kakor tek Ahimaaza, sina Zadokovega. In kralj veli: Dober mož je in prihaja z dobrim poročilom.',
        28: 'In Ahimaaz zakliče in reče kralju: Mir! Potem se pokloni pred kraljem z obrazom do tal in pravi: Hvaljen bodi Gospod, Bog tvoj, ki nam je izdal može, ki so vzdignili roko svojo zoper gospoda mojega, kralja.',
        29: 'In kralj vpraša: Je li dobro mladeniču Absalomu? Ahimaaz pa odgovori: Ko je Joab pošiljal kraljevega hlapca, mene, hlapca tvojega, sem videl velik hrup, pa ne vem, kaj je bilo.',
        30: 'Kralj veli: Stopi strani in stoj tu! In stopi tja in obstoji.',
        31: 'Glej, v tem pride Kušit in reče: Vesela vest gospodu mojemu kralju! Zakaj Gospod ti je danes pravico storil in te otel iz roke vseh, ki so se vzdignili zoper tebe.',
        32: 'Kralj pa vpraša Kušita: Je li dobro z mladeničem Absalomom? In Kušit odvrne: Zgodi se naj kakor temu mladeniču sovražnikom gospoda mojega kralja in vsem, ki se vzdigujejo zoper tebe, da ti store hudo!',
        33: 'In kralju se zelo užali in stopi v hram nad vrati in joče; in grede govori: O sin moj Absalom, sin moj, sin moj Absalom! Ah, da bi bil jaz umrl zate! O Absalom, sin moj, sin moj!',
    },
    19: {
        1: 'In oznanili so Joabu: Glej, kralj joče in žaluje po Absalomu!',
        2: 'In zmaga se je tisti dan obrnila v žalost vsemu ljudstvu, zakaj ljudstvo je slišalo ta dan, da se je pravilo: Kralju je žal za svojega sina.',
        3: 'In ljudstvo se po tihem prikrade v mesto ta dan, kakor se ljudstvo s sramom ukrade, ko je bežalo v boju.',
        4: 'Kralj pa si je zagrnil obraz in vpil z velikim glasom: O sin moj Absalom! Absalom, moj sin, moj sin!',
        5: 'In pride Joab v hišo h kralju in reče: Rdečico si danes pognal v obraze vseh hlapcev svojih, ki so ta dan rešili življenje tvoje in tvojih sinov in hčera, življenje tvojih žen in priležnic,',
        6: 's tem, da ljubiš tiste, ki te sovražijo, in mrziš te, ki te ljubijo. Zakaj pokazal si danes, da ne maraš za svoje kneze in hlapce; kajti danes vidim, ako bi le Absalom bil ostal živ, mi vsi pa bi bili pomrli danes, tebi bi bilo prav.',
        7: 'Sedaj pa vstani, pojdi ven in govori prijazno hlapcem svojim! Zakaj prisegam pri Gospodu: Ako ne pojdeš ven, ne ostane nocoj ne eden mož pri tebi, in to bo hujše zate nego vse hudo, ki te je zadelo od mladosti tvoje do sedaj.',
        8: 'Tedaj vstane kralj in sede med vrata. In oznanijo vsemu ljudstvu, rekoč: Glej, kralj sedi med vrati. In vse ljudstvo je prišlo pred kralja. Izrael pa je bil bežal, vsak v šator svoj.',
        9: 'In vse ljudstvo se je prepiralo po vseh rodovih Izraelovih, govoreč: Kralj nas je otel iz roke sovražnikov naših ter nas je oprostil pesti Filistejcev, in zdaj je moral bežati iz dežele pred Absalomom.',
        10: 'Absalom pa, ki smo ga pomazilili, da bodi nad nami, je mrtev na bojišču. Sedaj pa, zakaj ne izpregovorite besede, da pripeljemo kralja nazaj!',
        11: 'In kralj David pošlje k Zadoku in Abiatarju, duhovnikoma, veleč: Govorita starejšinam Judovim in recita: Zakaj hočete biti poslednji, da bi pripeljali kralja nazaj v hišo njegovo! Kaj ti govor vsega Izraela se je donesel kralju, da ga hočejo privesti v hišo njegovo.',
        12: 'Bratje moji ste, moja kost in meso, čemu bi torej bili poslednji, ko bodo peljali kralja nazaj!',
        13: 'In Amasu recita: Nisi li moja kost in meso? Bog mi stori to in še to prideni, ako ne boš vse svoje žive dni poveljnik vojske pred menoj na Joabovem mestu.',
        14: 'In nagnil je vseh Judovih mož srce, kakor srce enega moža, da so sporočili kralju: Vrni se ti in vsi hlapci tvoji!',
        15: 'Vrne se torej kralj in pride k Jordanu. In Judovci dospejo v Gilgal, gredoč naproti kralju, da ga prepeljejo čez Jordan.',
        16: 'In Simej, sin Gerov, Benjaminec, ki je prebival v Bahurimu, pohiti in pride doli z možmi Judovimi naproti kralju Davidu.',
        17: 'In bilo je ž njim tisoč mož iz Benjamina in Ziba, Savlove hiše služabnik, in petnajst sinov njegovih in dvajset hlapcev njegovih, in šli so čez Jordan pred kraljem.',
        18: 'Napravili so namreč brod, da prepeljejo kraljevo družino in store, kar mu je ugajalo. Simej pa, sin Gerov, pade pred kralja, ko se je hotel peljati čez Jordan,',
        19: 'in reče kralju: Ne prištevaj mi, gospod moj, krivice, in ne spominjaj se, kako se je pregrešil hlapec tvoj tisti dan, ko je bil šel gospod moj, kralj, iz Jeruzalema, in naj ne ohrani tega kralj v srcu.',
        20: 'Zakaj hlapec tvoj spoznava, da sem grešil; in poglej, jaz sem danes prvi šel od vse hiše Jožefove, da pridem doli naproti gospodu svojemu, kralju.',
        21: 'Abisaj pa, Zervijin sin, odgovori in reče: Ne bo li Simej usmrčen zato, ker je preklinjal maziljenca Gospodovega?',
        22: 'A David veli: Kaj imam z vama opraviti, sinova Zervije, da mi danes hočeta biti nasprotnika? Ali naj danes umre kdo v Izraelu? Ne vem li namreč, da sem danes zopet kralj nad Izraelom?',
        23: 'In Simeju reče kralj: Ne umreš. In kralj mu je prisegel.',
        24: 'Mefiboset, Savlov sin, je tudi prišel doli kralju naproti. Ni si pa snažil nog, ne ravnal brade, ne pral obleke od dne, ko je bil kralj odšel, do dne, ko se je vrnil domov v miru.',
        25: 'In zgodi se, ko pride v Jeruzalem kralju naproti, da ga kralj vpraša: Zakaj nisi šel z menoj, Mefiboset?',
        26: 'On pa odgovori: O gospod moj, kralj, hlapec moj me je okanil! Zakaj hlapec tvoj je dejal: Osedlam si osla, da bom jezdil na njem in šel h kralju, ker hlapec tvoj je hrom.',
        27: 'A on je še ovadil hlapca tvojega pred gospodom mojim, kraljem. Ali gospod moj, kralj, je kakor angel Božji! Stóri torej, kar se ti dobro vidi.',
        28: 'Zakaj očeta mojega vsa družina ni bila nič drugega kakor ljudje, smrti izročeni pred gospodom mojim, kraljem; a vendar si posadil hlapca svojega med tiste, ki jedo pri mizi tvoji. Kaj imam torej še pravice, da bi dalje vpil h kralju?',
        29: 'In kralj mu veli: Kaj toliko govoriš o svojih rečeh? Rekel sem: Ti in Ziba si vkup delita tiste njive!',
        30: 'In Mefiboset reče kralju: Lahko si tudi vse vzame, samo da se je gospod moj, kralj, vrnil v miru v hišo svojo!',
        31: 'In Barzilaj Gileadčan je prišel doli iz Rogelima in je šel s kraljem čez Jordan, da bi ga spremil čez Jordan.',
        32: 'Barzilaj pa je bil silno star, dobrih osemdeset let, in je oskrboval kralja z živežem, dokler je bival v Mahanaimu, kajti bil je jako bogat mož.',
        33: 'In kralj veli Barzilaju: Pojdi z menoj na ono stran in hočem te oskrbeti pri sebi v Jeruzalemu.',
        34: 'Barzilaj pa reče kralju: Koliko je še dni življenja mojega, da bi šel s kraljem gori v Jeruzalem?',
        35: 'Osemdeset let sem sedaj star: morem li razločevati med dobrim in hudim? More li hlapcu tvojemu tekniti, kar bo jedel in kar bo pil? Morem li še poslušati glas pevcev in pevk? Čemu naj torej bode hlapec tvoj še v nadlego gospodu svojemu, kralju?',
        36: 'Hlapec tvoj je samo hotel malo spremiti kralja čez Jordan, in zakaj bi mi kralj podelil tako povračilo?',
        37: 'Naj se sme, prosim, vrniti hlapec tvoj, da umrjem v mestu svojem, pri grobu očeta svojega in matere svoje. A glej, tu je hlapec tvoj Kimham, ta naj gre na ono stran z mojim gospodom kraljem, in njemu stóri, kar se ti vidi prav.',
        38: 'In kralj odgovori: Kimham naj torej gre z menoj, in storiti mu hočem, kar je dobro v tvojih očeh; tudi vse, česar boš želel od mene, storim zate.',
        39: 'In ko je prešlo vse ljudstvo čez Jordan in je tudi kralj bil na oni strani, poljubi kralj Barzilaja in ga blagoslovi. On pa se vrne v svoj kraj.',
        40: 'Kralj pa je šel čez v Gilgal in Kimham je šel ž njim; in vse ljudstvo Judovo je spremljalo kralja na ono stran, tudi polovica ljudstva Izraelovega.',
        41: 'In glej, vsi možje Izraelovi pridejo h kralju in mu reko: Zakaj so te ukradli bratje naši, možje Judovi, in so prepeljali kralja in družino njegovo čez Jordan in vse može Davidove ž njim?',
        42: 'A vsi možje Judovi odgovore možem Izraelovim: Kralj je nam bliže! Zakaj se srdite zato? Ali smo dobili kaj kraljeve hrane ali kako darilo od njega?',
        43: 'Možje Izraelovi pa odgovore možem Judovim in reko: Mi imamo desetkrat več pri kralju, in tudi Davidu smo več nego vi, zakaj ste nas torej zaničevali? In nismo li mi prvi govorili, da privedemo nazaj kralja svojega? Ali besede mož Judovih so bile trše nego mož Izraelovih besede.',
    },
    20: {
        1: 'In prigodi se, da je bil ondi mož Belijalov, po imenu Seba, sin Bikrijev, Benjaminec; ta zatrobi v trobento in reče: Ni nam deleža pri Davidu, ne dediščine pri sinu Jesejevem. Vsak v šator svoj, o Izrael!',
        2: 'Tedaj se vsi možje Izraelovi vzdignejo, da ne bi šli za Davidom, ter odidejo za Sebom, Bikrijevim sinom; ali možje Judovi so se držali kralja svojega od Jordana do Jeruzalema.',
        3: 'In David pride v hišo svojo v Jeruzalemu. In vzame kralj tistih deset žen priležnic, ki jih je bil popustil, da čuvajo hišo, in jih da v varstvo, ter jih je oskrboval z živežem, a ni hodil k njim. Tako so bile zaprte do dne smrti svoje, živeč v vdovstvu.',
        4: 'Nato veli kralj Amasu: Skliči mi može Judove na tretji dan, tudi sam pridi sem!',
        5: 'In Amasa odide sklicat Judovce, a se zamudi, da ni prišel ob določenem času.',
        6: 'Tedaj reče David Abisaju: Sedaj nam bo Seba, sin Bikrijev, več škodoval nego Absalom. Vzemi gospoda svojega hlapce in híti za njim, da si ne pridobi utrjenih mest ter nam uskoči izpred oči.',
        7: 'šli so torej za njim možje Joabovi in Keretejci in Peletejci in vsi junaki; šli so iz Jeruzalema, da zasledujejo Seba, sina Bikrijevega.',
        8: 'Ko so bili pri tistem velikem kamenu, ki je v Gibeonu, jim pride Amasa naproti. Joab pa je bil oblečen v vojaško suknjo in čeznjo prepasan s pasom in na njem je visel meč v nožnici ob bedru njegovem, in ko je postopil, se je meč iztaknil.',
        9: 'In Joab reče Amasu: Se ti li dobro godi, brat moj? In Joab prime z desnico Amasa za brado, da ga poljubi.',
        10: 'Amasa pa ni opazil meča, ki je bil v roki Joabovi, in on ga je ž njim pobodel pod rebra, da so se mu čreva izsula na zemljo, in ni ga pobodel v drugič; in je umrl. A Joab in Abisaj, brat njegov, sta se gnala za Sebom, sinom Bikrijevim.',
        11: 'In eden iz Joabovih hlapcev stopi poleg Amasa in reče: Kdor ljubi Joaba in kdor je za Davida, naj gre za Joabom!',
        12: 'Amasa pa se je valjal v krvi svoji sredi ceste. In ko je videl mož, da se ustavlja vse ljudstvo, odnese Amasa s ceste na polje ter vrže nanj oblačilo, videč, da se ustavi, kdorkoli gre mimo.',
        13: 'Ko je torej bil odpravljen s ceste, je šlo vse ljudstvo naprej za Joabom, da pode Seba, sina Bikrijevega.',
        14: 'Ta pa je bil šel skozi vse rodove Izraelove do Abela in Betmaaka in skozi ves kraj Berimcev; in zbrali so se in šli tudi za njim.',
        15: 'Oni pa so prišli ter ga oblegli v Abel-Betmaaki in so napravili nasip okoli mesta, da je stal proti zidovju; in vse ljudstvo, ki je bilo z Joabom, je podkopalo zid, da bi ga podrli.',
        16: 'Tedaj zakliče modra žena iz mesta: Čujte, čujte! Recite Joabu: Pristopi sem, da govorim s teboj!',
        17: 'In on se ji približa. Žena pa vpraša: Si li ti Joab? Odgovori: Sem. Tedaj mu reče: Čuj besede dekle svoje! On reče: Poslušam.',
        18: 'Tedaj govori ona, rekoč: V starih časih so rekali: Povprašajte za svet v Abelu! In s tem so končali vsako stvar.',
        19: 'Jaz sem eno iz miroljubnih in zvestih mest v Izraelu, in ti hočeš ugonobiti mesto in mater v Izraelu? Zakaj hočeš požreti dediščino Gospodovo?',
        20: 'In Joab odgovori in reče: Nikakor ne, nikakor ne, da bi jaz požiral ali razdeval!',
        21: 'Stvar ni taka, ampak mož z Efraimskega gorovja, Seba, sin Bikrijev, po imenu, je vzdignil roko svojo zoper kralja, zoper Davida. Izročite njega samega, in odidem od mesta. In žena reče Joabu: Glej, glava njegova se ti bo vrgla čez zid.',
        22: 'Nato gre žena in govori vsemu ljudstvu v modrosti svoji. In odsekajo glavo Sebu, sinu Bikrijevemu, in jo vržejo ven Joabu. In zatrobi na trobento, in razidejo se od mesta, vsak v mesto svoje. Joab pa se vrne v Jeruzalem h kralju.',
        23: 'Bil pa je Joab nad vso vojsko Izraelovo, in Benaja, sin Jojadov, je bil nad Keretejci in Peletejci;',
        24: 'in Adoram je bil nad robotniki, in Josafat, sin Ahiludov, je bil deželni letopisec,',
        25: 'in Seva je bil pisar, Zadok in Abiatar pa sta bila duhovnika,',
        26: 'tudi Ira Jairski je bil prvi dvornik Davidu.',
    },
    21: {
        1: 'In bila je lakota tri leta v dnevih Davidovih, leto za letom; in David je iskal obličja Gospodovega. In Gospod je dejal: Zaradi Savla je to in zaradi krvi, prelite od hiše njegove, ker je pomoril Gibeončane.',
        2: 'In kralj pokliče Gibeončane in govori ž njimi. (Gibeončani pa niso bili izmed sinov Izraelovih, ampak iz ostanka Amorejcev, in sinovi Izraelovi so jim prisegli mir. Toda Savel jih je poskušal iztrebiti v svoji gorečnosti za sinove Izraelove in Judove.)',
        3: 'In David reče Gibeončanom: Kaj naj storim za vas? In s čim naj storim poravnavo, da boste blagoslovili dediščino Gospodovo?',
        4: 'In Gibeončani mu reko: Ni nam za srebro ali za zlato v zadevi med nami in med Savlom in hišo njegovo, niti za to, da se kdo umori v Izraelu. In jim reče: Kar porečete, storim za vas.',
        5: 'In reko kralju: Tistega moža, ki nas je pokončeval in ki je izmišljal zoper nas, da bi bili potrebljeni, da nas ne bo v nobenem kraju Izraelovem,',
        6: 'naj se nam da sedem iz sinov njegovih, in obesimo jih Gospodu v Gibei Savlovi, v mestu izvoljenca Gospodovega. In kralj reče: Dam vam jih.',
        7: 'Ali kralj je prizanesel Mefibosetu, sinu Jonatana, sina Savlovega, zaradi prisege Gospodove, ki je bila med njima, med Davidom in Jonatanom, sinom Savlovim.',
        8: 'Vzame pa kralj dva sinova Ricpe, hčere Ajeve, ki ju je rodila Savlu, Armonija in Mefiboseta, in pet sinov Mihale, hčere Savlove, ki jih je rodila Adrielu, sinu Barzilaja Meholačana,',
        9: 'in jih da Gibeončanom v roke, in obesijo jih na gori pred Gospodom, in poginilo je teh sedem skupaj; in bili so usmrčeni ob žetvi, v prvih dneh, ko se je začela ječmenova žetev.',
        10: 'A Ricpa, hči Ajeva, vzame raševnik in si ga razgrne na skali, od začetka žetve dotlej, ko je voda kapljala z neba na obešence, in ni dopustila ptičem nebeškim, da sedejo nanje po dne, ne zverinam poljskim po noči.',
        11: 'In povedali so Davidu, kaj je storila Ricpa, hči Ajeva, priležnica Savlova.',
        12: 'In David odide in vzame kosti Savlove in kosti Jonatana, sinu njegovega, od meščanov v Jabesu v Gileadu, ki so jih bili ukradli z ulic v Betsanu, kjer so ju Filistejci obesili v dan, ko so umorili Savla na Gilboi;',
        13: 'in prinese odondod kosti Savlove in kosti Jonatana, sina njegovega. Zbrali so tudi kosti tistih, ki so bili obešeni.',
        14: 'In pokopali so kosti Savlove in Jonatana, sina njegovega, v pokrajini Benjaminovi v Zeli, v grobu Kisa, očeta njegovega, in storili so vse, kar je kralj zapovedal. In potem se je dal Bog izprositi za deželo.',
        15: 'In Filistejci so zopet začeli vojno z Izraelom. In David gre doli in služabniki njegovi ž njim in se bojujejo zoper Filistejce. In David je bil utrujen,',
        16: 'in Isbibenob, ki je bil iz sinov velikana, čigar sulica je tehtala tristo seklov brona, in je bil opasan z novim mečem, je nameraval ubiti Davida.',
        17: 'Ali Abisaj, sin Zervijin, mu je prišel v pomoč in je udaril Filistejca ter ga ubil. Tedaj so prisegli Davidu možje njegovi, rekoč: Nikdar več ne pojdeš z nami v boj, da ne ugasneš svetila Izraelu.',
        18: 'In zgodi se potem, da je bila zopet vojna s Filistejci v Gobu; tedaj je Sibekaj Husajec ubil Safa, ki je bil iz sinov velikanov.',
        19: 'In zopet je bila vojna s Filistejci v Gobu, in Elhanan, sin Jaare-orgimov, Betlehemčan, je ubil brata Goliata Gatovca, čigar suličišče je bilo kakor tkalsko vratilo.',
        20: 'In zopet je bila vojna v Gatu, kjer je bil mož velike postave, ki je imel na vsaki roki šest in na vsaki nogi šest prstov, štiriindvajset po številu; tudi ta se je bil rodil velikanu.',
        21: 'Ko pa je ta sramoto kidal na Izraela, ga je ubil Jonatan, sin Simeja, brata Davidovega.',
        22: 'Ti štirje so se rodili velikanu v Gatu, in padli so po roki Davidovi in po roki služabnikov njegovih.',
    },
    22: {
        1: 'In David je govoril Gospodu besede te pesmi v dan, ko ga je Gospod otel iz roke vseh sovražnikov njegovih in iz roke Savlove,',
        2: 'in dejal je: Gospod je skala moja in visok grad moj in rešitelj moj, prav moj.',
        3: 'Bog skale moje, v njem mi bode zavetje, ščit moj in rešenja mojega rog, visoka trdnjava moja in moje pribežališče. Moj rešitelj, ti me rešuješ nasilstva!',
        4: 'Hvale vrednega Gospoda bom klical in tako se rešim sovražnikov svojih.',
        5: 'Kajti valovi smrti so me zagrnili, hudourniki Belijalovi so me prestrašili.',
        6: 'Peklenske vezi so me opele, smrtne zanke so me zajele.',
        7: 'V stiski svoji sem klical Gospoda, da, klical sem k Bogu svojemu, in začul je glas moj iz svetišča svojega in vpitje moje je prišlo do ušes njegovih.',
        8: 'Tu se je zgenila in stresla zemlja, podstave nebes so se gibale in majale, ker se je srdil.',
        9: 'Dim se je valil iz nosnic njegovih, in ogenj iz ust njegovih je požiral, žerjavica je prhala od njega.',
        10: 'Nagnil je nebo ter stopil doli, in oblačna temota mu je bila pod nogami.',
        11: 'In sedeč na kerubu, je letel, in videti ga je bilo na vetra perotih.',
        12: 'In temo si je napravil za šatore okoli sebe, grmade vodá, roje oblakov.',
        13: 'Od svita pred njim se je vnela žerjavica ognjena.',
        14: 'Na nebesih je grmel Gospod, in Najvišji je dal slišati svoj glas.',
        15: 'In izstrelil je pšice ter sovražnike razkropil, strelo, in jih je zbegal.',
        16: 'Tedaj so se prikazale struge morja, podstave zemlje so se odgrnile po svarilu Gospodovem, od sape jeze njegove.',
        17: 'Iz višine je posegel in me prijel, potegnil me je iz mnogih vodá.',
        18: 'Rešil me je močnega neprijatelja mojega, sovražilcev mojih, ker so mi bili premočni.',
        19: 'Naskočili so me ob dnevu nesreče moje, a Gospod mi je bil podpora',
        20: 'in me je izpeljal na plano, rešil me je, ker me je ljubil.',
        21: 'Podelil mi je Gospod po pravičnosti moji, po čistosti mojih rok mi je povrnil.',
        22: 'Kajti držal sem se poti Gospodovih ter se nisem zlobno odvrnil od Boga svojega.',
        23: 'Zakaj vse sodbe njegove so bile pred mojimi očmi, in od postav njegovih nisem odstopil.',
        24: 'In popolnoma sem mu bil vdan ter sem se varoval, da ne ravnam krivično.',
        25: 'In povrnil mi je Gospod po pravičnosti moji, po čistosti moji pred njegovimi očmi.',
        26: 'Milosrčnemu se izkazuješ milosrčnega, popolnoma vdanemu se izkazuješ popolnega;',
        27: 'kdor je čist, njemu se kažeš čistega, a popačenemu nasprotnega.',
        28: 'In ljudstvo ubogo otimlješ, proti prevzetnim pa so tvoje oči, da jih ponižaš.',
        29: 'Kajti ti si svetilnica moja, o Gospod! Gospod razjasnjuje tmine moje.',
        30: 'Kajti s teboj prodiram skozi krdelo, z Bogom svojim preskakujem zid.',
        31: 'Tega Boga mogočnega pot je brezmadežna; govor Gospodov je prečiščen; ščit je vsem, ki pribegajo k njemu.',
        32: 'Kajti kdo je Bog mogočni razen Gospoda? in kdo skala razen našega Boga?',
        33: 'Bog mogočni je močna trdnjava moja in vodi v popolnosti mojo pot.',
        34: 'Stori noge moje enake jelenjim in me stavi na višine moje.',
        35: 'Vadi za boj roke moje, da napnem z ramo svojo lok bronasti.',
        36: 'Dal si mi tudi zveličanja svojega ščit, in ljubeznivost tvoja me je poveličala.',
        37: 'Razširil si prostor korakom mojim pod mano, in členki mojih nog niso omagovali.',
        38: 'Zasledoval sem sovražnike svoje in jih zatiral, in nisem se vrnil, dokler niso bili pokončani.',
        39: 'Pokončal sem jih in zdrobil, da ne morejo vstati, da, padli so mi pod noge.',
        40: 'Ker ti si me opasal z močjo za boj, upognil si podme nje, ki so se vzpenjali zoper mene.',
        41: 'In zapodil si v beg sovražnike moje, da jih ugonobim, ki me sovražijo.',
        42: 'Ozirali so se, a ni ga bilo, ki bi jih rešil – h Gospodu, a ni jih uslišal.',
        43: 'Tedaj sem jih strl kakor prah zemlje, pogazil in razteptal sem jih kakor blato na ulicah.',
        44: 'Ti si me tudi otel iz prepirov ljudstva mojega in si me ohranil, da bodem narodom za glavo; ljudstvo, ki ga nisem poznal, mi bo služilo.',
        45: 'Tujci se mi bodo vdajali z laskanjem; komaj začujejo o meni, se mi bodo pokorili.',
        46: 'Tujci bodo koprneli in pritrepetavali iz gradov svojih.',
        47: 'Živ je Gospod; in hvaljena bodi skala moja in naj se povišuje Bog, skala rešenja mojega,',
        48: 'ta Bog mogočni, ki mi daje maščevanje in spravlja ljudstva podme',
        49: 'in me izpeljava izsredi sovražnikov mojih. Da, ti me povzdiguješ nadnje, ki vstajajo zoper mene, siloviteža me otimlješ.',
        50: 'Zato te bom hvalil, o Gospod, med narodi in psalme prepeval imenu tvojemu.',
        51: 'Veliko in obilo rešenje daje kralju svojemu in milost izkazuje maziljencu svojemu, Davidu, in semenu njegovemu na veke.',
    },
    23: {
        1: 'Te pa so zadnje besede Davidove. David, sin Jesejev, govori, mož, ki je bil visoko postavljen, maziljenec Boga Jakobovega, sladki pevec psalmov v Izraelu govori:',
        2: 'Duh Gospodov je govoril po meni, in beseda njegova je bila na mojem jeziku.',
        3: 'Bog Izraelov je rekel, Skala Izraelova je meni govorila: Pride vladar ljudem, pravičen, ki vlada v strahu Božjem,',
        4: 'in bode kakor svetloba jutranja, ko solnce vzhaja, jutro brez oblakov: od njegovega sijaja po dežju poganja zelenjava iz zemlje.',
        5: 'Čeprav ni taka moja hiša pri Bogu, a vendar je storil večno zavezo z menoj, urejeno v vsem in zavarovano; kajti to je vse rešenje moje in vsa želja moja. Ali bi ne dal, da to vzraste?',
        6: 'Ali Belijalci bodo vsi kakor trnje, ki se zameta, ker ga ni jemati v roko,',
        7: 'ampak mož, ki se ga dotakne, si preskrbi železo in suličišče; in popolnoma bodo sežgani z ognjem v kraju svojem.',
        8: 'Ta so imena junakov, ki jih je imel David: Joseb Basebet Tahkemončan, prvi poveljnikov; on je bil tisti Adino Ezni proti osemsto, ki jih je pobil naenkrat.',
        9: 'In za njim je bil Eleazar, sin Dodaja, sinu Ahohija, eden izmed treh junakov pri Davidu, ko so zasmehovali Filistejce, ki so bili ondi zbrani v boj, ko so odšli možje Izraelovi;',
        10: 'on je vstal in pobijal Filistejce, dokler mu ni roka onemogla in otrpnila na meču; in Gospod je storil veliko rešitev tisti dan. Ljudstvo pa se je vrnilo za njim, samo da pobere plen.',
        11: 'In za njim je bil Sama, sin Ageja Hararca. In Filistejci so se zbrali v eno krdelo, kjer je bila njiva polna leče, in ljudstvo je bežalo pred Filistejci.',
        12: 'Tedaj se je on postavil sredi njive in jo je otel in pobil Filistejce; in Gospod je storil veliko rešitev.',
        13: 'In trije izmed tridesetih načelnikov so šli doli in prišli k Davidu ob žetvi v Adulamsko votlino; in krdelo Filistejcev je bilo utaborjeno v dolini Refaimov.',
        14: 'David pa je bil takrat v trdnjavi, in straža Filistejcev je bila tedaj v Betlehemu.',
        15: 'In Davida je obšla želja in je rekel: O, da bi mi kdo dal piti vode iz studenca v Betlehemu, ki je pri vratih!',
        16: 'In ti trije junaki so prodrli ostrog Filistejcev ter zajeli vode iz studenca v Betlehemu, ki je pri vratih, in so je vzeli ter prinesli Davidu. A on je ni hotel piti in jo je izlil kot pitno daritev Gospodu,',
        17: 'in je rekel: Nikakor ne, o Gospod, da bi jaz to storil! Naj li pijem kri mož, ki so šli tja in vnemar pustili življenje! In ni je hotel piti. To so storili ti trije junaki. –',
        18: 'In Abisaj, Joabov brat, sin Zervijin, je bil glava trem. On je mahnil s sulico svojo po treh sto in jih pobil; in imel je sloveče ime med tremi.',
        19: 'Ni li bil najslavnejši izmed teh treh, da jim je postal knez? Toda prvih treh ni dosegel.',
        20: 'In Benaja, sin Jojadov, sin hrabrega moža iz Kabzeela, ki je storil velika dela, ta je ubil dva sina Ariela iz Moaba; ta je tudi stopil doli in ubil leva sredi jame, ko je bil sneg.',
        21: 'In ubil je Egipčana, velikega moža, in Egipčan je imel v roki sulico, a on je šel k njemu doli s palico in iztrgal sulico Egipčanu iz roke in ga je umoril z lastno sulico njegovo.',
        22: 'To je storil Benaja, sin Jojadov, in imel je sloveče ime med tremi junaki.',
        23: 'On je bil slavnejši nego tistih trideset, ali prvih treh ni dosegel.',
        24: 'Asahel, brat Joabov, je bil eden iz trideseterih, Elhanan, sin Dodov iz Betlehema,',
        25: 'Sama Harodčan, Elika Harodčan,',
        26: 'Helez Paltičan, Ira, sin Ikešev, Tekojčan,',
        27: 'Abiezer Anatotčan, Mebunaj Husajec,',
        28: 'Zalmon Ahohovec, Maharaj Netofatčan,',
        29: 'Heleb, sin Baanov, Netofatčan, Itaj, sin Ribajev iz Gibee sinov Benjaminovih,',
        30: 'Benaja Piratončan, Hidaj od potokov v Gaasu,',
        31: 'Abialbon Arbatski, Azmavet Barhumčan,',
        32: 'Eljahba Salbončan, iz sinov Jasenovih Jonatan,',
        33: 'Sama Hararovec, Ahiam, sin Sararjev, Ararovec,',
        34: 'Elifelet, sin Ahasbaja, sinu Maakatovca, Eliam, sin Ahitofela Gilonskega,',
        35: 'Hezro Karmelčan, Paaraj Arbski,',
        36: 'Igal, sin Natana iz Zobe, Bani Gadovec,',
        37: 'Zelek Amonec, Naharaj Beerotčan, oproda Joaba, sinu Zervijinega,',
        38: 'Ira Jitričan, Gareb Jitričan,',
        39: 'Urija Hetejec, vseh sedemintrideset.',
    },
    24: {
        1: 'In srd Gospodov se je zopet vnel zoper Izraelce, in izpodbodel je Davida zoper nje, rekoč: Pojdi, seštej Izraela in Judo.',
        2: 'In kralj reče Joabu, poveljniku vojske, ki je bil pri njem: Prehodi, prosim, vse rodove Izraelove, od Dana do Bersebe, in preštejte ljudstvo, da bi vedel število ljudstva.',
        3: 'In Joab reče kralju: Naj prida Gospod, Bog tvoj, k ljudstvu, kolikorkoli ga je, še stokrat toliko, dokler to vidijo oči gospoda mojega, kralja! Ali zakaj to veseli gospoda mojega, kralja?',
        4: 'Toda beseda kraljeva je obveljala zoper Joaba in zoper poveljnike vojske. In odidejo Joab in poveljniki vojske od obličja kraljevega, da preštejejo ljudstvo Izraelovo.',
        5: 'In šli so čez Jordan in se utaborili v Aroerju, na desno ob mestu, ki je sredi doline Gadove, in proti Jazerju.',
        6: 'Potem so prišli v Gilead in v pokrajino Tahtim-hodši; in prišli so v Danjaan in v okolico Sidonsko,',
        7: 'in dospeli so k utrjenemu mestu Tiru in k vsem mestom Hevejcev in Kanaancev ter šli potem v južno stran Judovo, proti Bersebi.',
        8: 'In prehodili so vso deželo in prišli v Jeruzalem ob koncu devetih mesecev in dvajsetih dni.',
        9: 'In Joab je dal število preštetega ljudstva kralju; in bilo je v Izraelu osemsto tisoč vojakov, ki so izdirali meč, in v Judi petsto tisoč mož.',
        10: 'A Davidu je očitalo srce, potem ko je bil seštel ljudstvo. In reče David Gospodu: Hudo sem grešil s tem, kar sem storil; ali sedaj, o Gospod, odpravi hlapca svojega krivico, kajti ravnal sem zelo nespametno.',
        11: 'In ko vstane David zjutraj, pride beseda Gospodova k proroku Gadu, vidcu Davidovemu, govoreč:',
        12: 'Pojdi in veli Davidu: Tako pravi Gospod: Troje ti ponujam, izberi si eno, da naj ti storim.',
        13: 'Pride torej Gad k Davidu in mu pove ter mu reče: Ali naj ti pride sedem let lakote v deželo tvojo? Ali hočeš tri mesece bežati pred nasprotniki svojimi, da te oni podijo? Ali naj razsaja tri dni kuga v deželi tvoji? Sedaj pa premisli in poglej, kakšen odgovor naj dam njemu, ki me je poslal.',
        14: 'In David reče Gadu: V stiski sem veliki! Naj rajši pademo v roko Gospodovo, kajti usmiljenje njegovo je veliko, in nikar naj ne padem v roko človeško!',
        15: 'In Gospod je poslal kugo nad Izraela od jutra do določenega časa; in pomrlo je iz ljudstva od Dana do Bersebe sedemdeset tisoč ljudi.',
        16: 'In ko iztegne angel roko proti Jeruzalemu, da ga pogubi, je bilo žal Gospodu hudega in veli angelu, ki je pokončeval ljudstvo: Dosti je, odtegni zdaj roko svojo! In angel Gospodov je bil pri gumnu Aravna Jebusejca.',
        17: 'In David reče Gospodu, ko je videl angela, ki je pobijal ljudstvo: Glej, jaz sem grešil in jaz sem ravnal popačeno, te ovce pa, kaj so storili? Roka tvoja bodi, prosim, zoper mene in zoper očeta mojega hišo!',
        18: 'In Gad pride tisti dan k Davidu in mu reče: Pojdi gori, zgradi oltar Gospodu na gumnu Aravna Jebusejca.',
        19: 'In David je šel gori po besedi Gadovi, kakor je ukazal Gospod.',
        20: 'In Aravna se ozre in zagleda kralja in služabnike njegove, da gredo proti njemu; in Aravna izide in se prikloni kralju z obrazom do tal.',
        21: 'In Aravna reče: Zakaj je prišel gospod moj, kralj, k hlapcu svojemu? David pa reče: Kupiti hočem gumno od tebe, da zgradim oltar Gospodu, da neha kuga med ljudstvom.',
        22: 'In Aravna reče Davidu: Vzame naj gospod moj, kralj, in daruje, kar se mu vidi dobro: glej, tu so voli za žgalno daritev in mlatilnice in oprava volovska za drva.',
        23: 'Vse to, o kralj, Aravna pokloni kralju. Še reče Aravna kralju: Gospod, Bog tvoj, te milo sprejmi!',
        24: 'A kralj reče Aravnu: Nikar, ampak res hočem to kupiti od tebe za ceno, ker nočem darovati žgalnih daritev Gospodu, Bogu svojemu, ki bi jih brez stroškov imel. Kupil je torej David gumno in vole za petdeset seklov srebra.',
        25: 'In David je ondi zgradil oltar Gospodu ter daroval žgalne in mirovne daritve. In Gospod se je dal izprositi za deželo, in kuga je nehala med Izraelom.',
    },
}
